functions.menu_options_input:
void menu_options_input()
{
    int quit = 0;
    int selector = 1; // 0
    int x_pos = -6;
    #if ANDROID
    int OPTIONS_NUM = 6;
    #else
    int OPTIONS_NUM = 5;
    #endif

    controloptionsMenu = 1;
    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, x_pos-1, 0, Tr("Control Options"));

        #if PSP
        if(savedata.usejoy)
        {
            _menutext((selector == 0), -4, -2, Tr("Analog Pad Enabled"));
        }
        else
        {
            _menutext((selector == 0), -4, -2, Tr("Analog Pad Disabled"));
        }
        #elif WII
        if(savedata.usejoy)
        {
            _menutext((selector == 0), -4, -2, Tr("Nunchuk Analog Enabled"));
        }
        else
        {
            _menutext((selector == 0), -4, -2, Tr("Nunchuk Analog Disabled"));
        }
        #else
        if(savedata.usejoy)
        {
            _menutext((selector == 0), x_pos, -2, Tr("GamePads Enabled"));
            if(!control_getjoyenabled())
            {
                _menutext((selector == 0), x_pos+11, -2, Tr(" - Device Not Ready"));
            }
        }
        else
        {
            _menutext((selector == 0), x_pos, -2, Tr("GamePads Disabled"));
        }
        #endif

        _menutext((selector == 1), x_pos,-1, Tr("Setup Player 1..."));
        _menutext((selector == 2), x_pos, 0, Tr("Setup Player 2..."));
        _menutext((selector == 3), x_pos, 1, Tr("Setup Player 3..."));
        _menutext((selector == 4), x_pos, 2, Tr("Setup Player 4..."));
        #if ANDROID
        if(savedata.is_touchpad_vibration_enabled)
        {
            _menutext((selector == 5), x_pos, 4, Tr("Touchpad Vibration Enabled"));
        }
        else
        {
            _menutext((selector == 5), x_pos, 4, Tr("Touchpad Vibration Disabled"));
        }
        _menutextm((selector == 6), 6, 0, Tr("Back"));
        #else
        _menutextm((selector == 5), 5, 0, Tr("Back"));
        #endif

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(selector < 0)
        {
            selector = OPTIONS_NUM;
        }
        if(selector > OPTIONS_NUM)
        {
            selector = 0;
        }
        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                control_usejoy((savedata.usejoy ^= 1));
                break;
            case 1:
                keyboard_setup(0);
                break;
            case 2:
                keyboard_setup(1);
                break;
            case 3:
                keyboard_setup(2);
                break;
            case 4:
                keyboard_setup(3);
                break;
            #if ANDROID
            case 5:
                savedata.is_touchpad_vibration_enabled ^= 1;
                break;
            #endif
            default:
                quit = (bothnewkeys & FLAG_ANYBUTTON);
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
    controloptionsMenu = 0;
}

functions.menu_options_sound:
void menu_options_sound()
{

    int quit = 0;
    int selector = 0;
    int dir;
    int col1 = -8;
    int col2 = 6;

    soundoptionsMenu = 1;
    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("Sound Options"));
        _menutext((selector == 0), col1, -2, Tr("Sound Volume:"));
        _menutext((selector == 0), col2, -2, "%i", savedata.soundvol);
        _menutext((selector == 1), col1, -1, Tr("SFX Volume:"));
        _menutext((selector == 1), col2, -1, "%i", savedata.effectvol);
        _menutext((selector == 2), col1, 0, Tr("Music Volume:"));
        _menutext((selector == 2), col2, 0, "%i", savedata.musicvol);
        _menutext((selector == 3), col1, 1, Tr("BGM:"));
        _menutext((selector == 3), col2, 1, (savedata.usemusic ? Tr("Enabled") : Tr("Disabled")));
        _menutext((selector == 4), col1, 2, Tr("Show Titles:"));
        _menutext((selector == 4), col2, 2, (savedata.showtitles ? Tr("Yes") : Tr("No")));
        _menutext((selector == 5), col1, 3, Tr("Advanced Options..."));
        _menutextm((selector == 6), 6, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(selector < 0)
        {
            selector = 6;
        }
        if(selector > 6)
        {
            selector = 0;
        }

        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {
            dir = 0;

            if(bothnewkeys & FLAG_MOVELEFT)
            {
                dir = -1;
            }
            else if(bothnewkeys & FLAG_MOVERIGHT)
            {
                dir = 1;
            }

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                savedata.soundvol += dir;
                if(savedata.soundvol < 0)
                {
                    savedata.soundvol = 0;
                }
                if(savedata.soundvol > 15)
                {
                    savedata.soundvol = 15;
                }
                SB_setvolume(SB_VOICEVOL, savedata.soundvol);
                break;
            case 1:
                savedata.effectvol += 4 * dir;
                if(savedata.effectvol < 0)
                {
                    savedata.effectvol = 0;
                }
                if(savedata.effectvol > 512)
                {
                    savedata.effectvol = 512;
                }
                break;
            case 3:
                if(!dir)
                {
                    break;
                }
                if(!savedata.usemusic)
                {
                    savedata.usemusic = 1;
                    music("data/music/remix", 1, 0);
                }
                else
                {
                    savedata.usemusic = 0;
                    sound_close_music();
                }
                break;
            case 2:
                savedata.musicvol += 4 * dir;
                if(savedata.musicvol < 0)
                {
                    savedata.musicvol = 0;
                }
                if(savedata.musicvol > 512)
                {
                    savedata.musicvol = 512;
                }
                sound_volume_music(savedata.musicvol, savedata.musicvol);
                break;
            case 4:
                savedata.showtitles = !savedata.showtitles;
                break;
            case 5:
                menu_options_soundcard();
                break;
            default:
                quit = 1;
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
    soundoptionsMenu = 0;
}

functions.menu_options_config:
void menu_options_config()     //  OX. Load from / save to default.cfg. Restore OpenBoR "factory" settings.
{
    int quit = 0;
    int selector = 0;
    int saved = 0;
    int loaded = 0;
    int restored = 0;

    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("Configuration Settings"));

        if(saved == 1)
        {
            _menutextm((selector == 0), -3, 0, Tr("Save Settings To Default.cfg%s"), Tr("  Done!"));
        }
        else
        {
            _menutextm((selector == 0), -3, 0, Tr("Save Settings To Default.cfg%s"), "");
        }

        if(loaded == 1)
        {
            _menutextm((selector == 1), -2, 0, Tr("Load Settings From Default.cfg%s"), Tr("  Done!"));
        }
        else
        {
            _menutextm((selector == 1), -2, 0, Tr("Load Settings From Default.cfg%s"), "");
        }

        if(restored == 1)
        {
            _menutextm((selector == 2), -1, 0, Tr("Restore OpenBoR Defaults%s"), Tr("  Done!"));
        }
        else
        {
            _menutextm((selector == 2), -1, 0, Tr("Restore OpenBoR Defaults%s"), "");
        }

        _menutextm((selector == 3), 6, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }

        if(selector < 0)
        {
            selector = 3;
        }
        if(selector > 3)
        {
            selector = 0;
        }

        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                saveasdefault();
                saved = 1;
                break;

            case 1:
                loadfromdefault();
                //borShutdown(2, "\nSettings Loaded From Default.cfg. Restart Required.\n\n");
                init_videomodes(0);
                if(!video_set_mode(videomodes))
                {
                    borShutdown(1, "Unable to set video mode: %d x %d!\n", videomodes.hRes, videomodes.vRes);
                }
                SB_setvolume(SB_VOICEVOL, savedata.soundvol);
                sound_volume_music(savedata.musicvol, savedata.musicvol);
                loaded = 1;
                break;
            case 2:
                clearsettings();
                //borShutdown(2, "\nSettings Loaded From Default.cfg. Restart Required.\n\n");
                init_videomodes(0);
                if(!video_set_mode(videomodes))
                {
                    borShutdown(1, "Unable to set video mode: %d x %d!\n", videomodes.hRes, videomodes.vRes);
                }
                SB_setvolume(SB_VOICEVOL, savedata.soundvol);
                sound_volume_music(savedata.musicvol, savedata.musicvol);
                restored = 1;
                break;
            default:
                quit = 1;
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
}

functions.menu_options_debug:
void menu_options_debug()
{
    #define MENU_POS_Y              -4
    #define MENU_ITEMS_MARGIN_Y     2
    #define COLUMN_1_POS_X          -11
    #define COLUMN_2_POS_X          COLUMN_1_POS_X + 14
    #define MENU_ITEM_FIRST_INDEX   0

    // Selections enumerator. All
    // selection items should be placed
    // here first.
    typedef enum
    {
        // First item can be
        // whatever we like,
        // but it must be set
        // to the MENU_ITEM_FIRST_INDEX
        // constant.
        ITEM_PERFORMANCE = MENU_ITEM_FIRST_INDEX,

        // Items between the first
        // and last can go in any
        // order.
        ITEM_POSITION,
        ITEM_FEATURES,
        ITEM_COL_ATTACK,
        ITEM_COL_BODY,
        ITEM_COL_RANGE,

        // This is the "Back"
        // selection and should
        // always be last.
        ITEM_EXIT
    } e_selections;

    int pos_y;
    int quit                = 0;
    e_selections selector   = 0;
    bothnewkeys             = 0;

    while(!quit)
    {
        // Display menu title.
        _menutextm(2, MENU_POS_Y, 0, Tr("Debug Settings"));

        // Menu items.
        // Y position is controlled by a incremented integer.
        // Integer has a base value of the Menu title Y
        // plus static offset. Below each item, this Y value
        // increments by one. We can then add or remove
        // menu items here and the on screen position will
        // take care of itself without us needing to mess
        // with a bunch of hard constants.

        // Reset menu item position Y.
        pos_y = MENU_POS_Y + MENU_ITEMS_MARGIN_Y;

        _menutext((selector == ITEM_PERFORMANCE),    COLUMN_1_POS_X, pos_y, Tr("Performance:"));
        _menutext((selector == ITEM_PERFORMANCE),    COLUMN_2_POS_X, pos_y, (savedata.debuginfo ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_POSITION),       COLUMN_1_POS_X, pos_y, Tr("Position:"));
        _menutext((selector == ITEM_POSITION),       COLUMN_2_POS_X, pos_y, (savedata.debug_position ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_FEATURES),       COLUMN_1_POS_X, pos_y, Tr("Features:"));
        _menutext((selector == ITEM_FEATURES),       COLUMN_2_POS_X, pos_y, (savedata.debug_features ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_COL_ATTACK),     COLUMN_1_POS_X, pos_y, Tr("Collision Attack:"));
        _menutext((selector == ITEM_COL_ATTACK),     COLUMN_2_POS_X, pos_y, (savedata.debug_collision_attack ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_COL_BODY),       COLUMN_1_POS_X, pos_y, Tr("Collision Body:"));
        _menutext((selector == ITEM_COL_BODY),       COLUMN_2_POS_X, pos_y, (savedata.debug_collision_body ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_COL_RANGE),      COLUMN_1_POS_X, pos_y, Tr("Range:"));
        _menutext((selector == ITEM_COL_RANGE),      COLUMN_2_POS_X, pos_y, (savedata.debug_collision_range ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        // Display exit title
        _menutextm((selector == ITEM_EXIT), pos_y + (MENU_ITEMS_MARGIN_Y), 0, Tr("Back"));

        // Run an engine update.
        update((level != NULL), 0);

        // If user presses up/down or esc, let's act accordingly.
        if(bothnewkeys & (FLAG_MOVEUP | FLAG_MOVEDOWN | FLAG_ESC))
        {
            // Play beep if available.
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            // If user presses escape, then set quit
            // flag immediately. Else wise, increment
            // or decrement selector as needed.
            if(bothnewkeys & FLAG_ESC)
            {
                quit = 1;
            }
            else if(bothnewkeys & FLAG_MOVEUP)
            {
                // If we are at the top item, loop
                // to last. Otherwise, move one up.
                if(selector <= MENU_ITEM_FIRST_INDEX)
                {
                    selector = ITEM_EXIT;
                }
                else
                {
                    --selector;
                }
            }
            else if(bothnewkeys & FLAG_MOVEDOWN)
            {
                // If we are at the last item
                // (which should be "back"), then
                // loop back to first. Otherwise
                // move one down.
                if(selector >= ITEM_EXIT)
                {
                    selector = MENU_ITEM_FIRST_INDEX;
                }
                else
                {
                    ++selector;
                }
            }
        }


        // Toggle selection value on left/right or
        // trigger button press.
        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {
            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            // This is where menu items are executed.
            switch(selector)
            {
                case ITEM_PERFORMANCE:
                    savedata.debuginfo = !savedata.debuginfo;
                    break;
                case ITEM_POSITION:
                    savedata.debug_position = !savedata.debug_position;
                    break;
                case ITEM_FEATURES:
                    savedata.debug_features = !savedata.debug_features;
                    break;
                case ITEM_COL_ATTACK:
                    savedata.debug_collision_attack = !savedata.debug_collision_attack;
                    break;
                case ITEM_COL_BODY:
                    savedata.debug_collision_body = !savedata.debug_collision_body;
                    break;
                case ITEM_COL_RANGE:
                    savedata.debug_collision_range = !savedata.debug_collision_range;
                    break;
                case ITEM_EXIT:
                    quit = 1;
            }
        }
    }
    savesettings();
    bothnewkeys = 0;

    #undef MENU_POS_Y
    #undef MENU_ITEMS_MARGIN_Y
    #undef COLUMN_1_POS_X
    #undef COLUMN_2_POS_X
    #undef MENU_ITEM_FIRST_INDEX
}

functions.menu_options_system:
void menu_options_system()
{
    #define SYS_OPT_Y_POS -4

    enum {
        SYS_OPT_LOG,
        SYS_OPT_VSDAMAGE,
        SYS_OPT_CHEATS,
        SYS_OPT_DEBUG,
        SYS_OPT_CONFIG,
        SYS_OPT_PSP_CPUSPEED,
        SYS_OPT_BACK
    };

    int quit = 0;
    int selector = 0;
    int col1 = -11;
    int col2 = col1+14;
    int ex_labels = 0;
    int RET = SYS_OPT_BACK-1;

#if PSP
    int dir = 0;
    int batteryPercentage = 0;
    int batteryLifeTime = 0;
    int externalPower = 0;
#endif

    systemoptionsMenu = 1;
    bothnewkeys = 0;
    if (nodebugoptions) ex_labels = 1;
    RET -= ex_labels;

    while(!quit)
    {
        _menutextm(2, SYS_OPT_Y_POS-2, 0, Tr("System Options"));

        _menutext(0, col1, SYS_OPT_Y_POS, Tr("Total RAM:"));
        _menutext(0, col2, SYS_OPT_Y_POS, Tr("%s KB"), commaprint(getSystemRam(KBYTES)));

        _menutext(0, col1, SYS_OPT_Y_POS+1, Tr("Used RAM:"));
        _menutext(0, col2, SYS_OPT_Y_POS+1, Tr("%s KB"), commaprint(getUsedRam(KBYTES)));

        _menutext(0, col1, SYS_OPT_Y_POS+2, Tr("Max Players:"));
        _menutext(0, col2, SYS_OPT_Y_POS+2, Tr("%i"), levelsets[current_set].maxplayers);

        _menutext((selector == SYS_OPT_LOG), col1, SYS_OPT_Y_POS+4, Tr("File Logging:"));
        _menutext((selector == SYS_OPT_LOG), col2, SYS_OPT_Y_POS+4, (savedata.uselog ? Tr("Enabled") : Tr("Disabled")));

        _menutext((selector == SYS_OPT_VSDAMAGE), col1, SYS_OPT_Y_POS+5, Tr("Versus Damage:"), 0);
        if(versusdamage == 0)
        {
            _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Disabled by Module"));
        }
        else if(versusdamage == 1)
        {
            _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Enabled by Module"));
        }
        else
        {
            if(savedata.mode)
            {
                _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Disabled"));    //Mode 1 - Players CAN'T attack each other
            }
            else
            {
                _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Enabled"));    //Mode 2 - Players CAN attack each other
            }
        }

        _menutext((selector == SYS_OPT_CHEATS), col1, SYS_OPT_Y_POS+6, Tr("Cheats:"));
        _menutext((selector == SYS_OPT_CHEATS), col2, SYS_OPT_Y_POS+6, forcecheatsoff ? Tr("Disabled by Module") : (cheats ? Tr("On") : Tr("Off")));
        if(!nodebugoptions) _menutext((selector == SYS_OPT_DEBUG), col1, SYS_OPT_Y_POS+7, Tr("Debug Settings..."));

#ifndef DC

        _menutext((selector == SYS_OPT_CONFIG-ex_labels), col1, SYS_OPT_Y_POS+8-ex_labels, Tr("Config Settings..."));

#endif

#if PSP
        externalPower = scePowerIsPowerOnline();
        _menutext((selector == SYS_OPT_PSP_CPUSPEED), col1, 4-ex_labels, Tr("CPU Speed:"));
        _menutext((selector == SYS_OPT_PSP_CPUSPEED), col2, 4-ex_labels, "%d MHz", scePowerGetCpuClockFrequency());
        if(!externalPower)
        {
            batteryPercentage = scePowerGetBatteryLifePercent();
            batteryLifeTime = scePowerGetBatteryLifeTime();
            _menutext(0, col1, 5-ex_labels, Tr("Battery:"));
            if(batteryPercentage < 0 || batteryLifeTime < 0)
            {
                _menutext(0, col2, 5-ex_labels, Tr("Calculating..."));
            }
            else
            {
                _menutext(0, col2, 5-ex_labels, "%d%% - %02d:%02d", batteryPercentage, batteryLifeTime / 60, batteryLifeTime - (batteryLifeTime / 60 * 60));
            }
        }
        else
        {
            _menutext(0, col1, 5-ex_labels, Tr("Charging:"));
            _menutext(0, col2, 5-ex_labels, Tr("%d%% AC Power"), scePowerGetBatteryLifePercent());
        }
        RET = 6-ex_labels;
#endif

        _menutextm((selector == RET), SYS_OPT_Y_POS+11-ex_labels, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;
            sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
        }

        if(selector < 0)
        {
            selector = RET;
        }
        if(selector > RET)
        {
            selector = 0;
        }

        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {

#if PSP
            dir = 0;
            if(bothnewkeys & FLAG_MOVELEFT)
            {
                dir = -1;
            }
            else if(bothnewkeys & FLAG_MOVERIGHT)
            {
                dir = 1;
            }
#endif

            sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);

                 if (selector==RET) quit = 1;
            else if (selector==SYS_OPT_LOG) savedata.uselog =  !savedata.uselog;
            else if (selector==SYS_OPT_VSDAMAGE)
            {
                if(versusdamage > 1)
                {
                    if(savedata.mode)
                    {
                        savedata.mode = 0;
                    }
                    else
                    {
                        savedata.mode = 1;
                    }
                }
            }
            else if (selector==SYS_OPT_CHEATS) cheats = !cheats;
            else if (selector==SYS_OPT_DEBUG && !nodebugoptions) menu_options_debug();
#ifndef DC
            else if (selector==SYS_OPT_CONFIG-ex_labels) menu_options_config();
#endif

#ifdef PSP
            else if (selector==SYS_OPT_PSP_CPUSPEED-ex_labels)
            {
                savedata.pspcpuspeed += dir;
                if(savedata.pspcpuspeed < 0)
                {
                    savedata.pspcpuspeed = 2;
                }
                if(savedata.pspcpuspeed > 2)
                {
                    savedata.pspcpuspeed = 0;
                }

                switch(savedata.pspcpuspeed)
                {
                case 0:
                    scePowerSetClockFrequency(222, 222, 111);
                    break;
                case 1:
                    scePowerSetClockFrequency(266, 266, 133);
                    break;
                case 2:
                    scePowerSetClockFrequency(333, 333, 166);
                    break;
                }
            }
#endif
            else quit = 1;
        }
    }
    savesettings();
    bothnewkeys = 0;
    systemoptionsMenu = 0;

    #undef SYS_OPT_Y_POS
}

functions.menu_options_video:
void menu_options_video()
{
    int quit = 0;
    int selector = 0;
    int dir;
    int col1 = -15, col2 = 1;

    videooptionsMenu = 1;
    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("Video Options"));
        _menutext((selector == 0), col1, -3, Tr("Brightness:"));
        _menutext((selector == 0), col2, -3, "%i", savedata.brightness);
        _menutext((selector == 1), col1, -2, Tr("Gamma:"));
        _menutext((selector == 1), col2, -2, "%i", savedata.gamma);
        _menutext((selector == 2), col1, -1, Tr("Window Offset:"));
        _menutext((selector == 2), col2, -1, "%i", savedata.windowpos);

#if OPENDINGUX
        _menutext((selector == 3), col1, 0, Tr("Display Mode:"));
        _menutext((selector == 3), col2, 0, savedata.fullscreen ? Tr("Full") : Tr("Window"));
        _menutextm((selector == 4), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 4;
        }
        if(selector > 4)
        {
            selector = 0;
        }
#endif

#if DC || GP2X || VITA
        _menutextm((selector == 3), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 3;
        }
        if(selector > 3)
        {
            selector = 0;
        }
#endif

#if WII
        _menutext((selector == 3), col1, 0, Tr("Display Mode:"));
        _menutext((selector == 3), col2, 0, (savedata.stretch ? Tr("Stretch to Screen") : Tr("Preserve Aspect Ratio")));
        _menutextm((selector == 4), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 4;
        }
        if(selector > 4)
        {
            selector = 0;
        }
#endif

#if SDL
#if !defined(GP2X) && !defined(OPENDINGUX)
        _menutext((selector == 3), col1, 0, Tr("Display Mode:"));
        _menutext((selector == 3), col2, 0, savedata.fullscreen ? Tr("Full") : Tr("Window"));

        _menutext((selector == 4), col1, 1, Tr("Video Backend:"));
        _menutext((selector == 4), col2, 1, (opengl ? Tr("OpenGL") : Tr("SDL")));

        _menutext((selector == 5), col1, 2, Tr("Scale:"));
#ifdef ANDROID
        if(savedata.hwscale == 0)
#else
		if(savedata.fullscreen)
#endif
        {
            _menutext((selector == 5), col2, 2, Tr("Automatic"));
        }
        else
        {
            _menutext((selector == 5), col2, 2, "%4.2fx - %ix%i", savedata.hwscale, (int)(videomodes.hRes * savedata.hwscale), (int)(videomodes.vRes * savedata.hwscale));
        }

        _menutext((selector == 6), col1, 3, Tr("Hardware Filter:"));
        {
            char *filterName;
            if (savedata.hwscale == 1.0 && !savedata.fullscreen)
                filterName = "Disabled";
            else if (opengl)
                filterName = "High Quality";
            else if (savedata.hwfilter)
                filterName = "Simple";
            else
                filterName = "Bilinear";
            _menutext((selector == 6), col2, 3, Tr(filterName));
        }

        _menutext((selector == 7), col1, 4, Tr("Software Filter:"));
        _menutext((selector == 7), col2, 4, ((savedata.hwscale >= 2.0 || savedata.fullscreen) ? Tr(GfxBlitterNames[savedata.swfilter]) : Tr("Disabled")));

        if(savedata.fullscreen)
        {
            _menutext((selector == 8), col1, 5, Tr("Fullscreen Type:"));
            _menutext((selector == 8), col2, 5, (savedata.stretch ? Tr("Stretch to Screen") : Tr("Preserve Aspect Ratio")));
        }
        else if(selector == 8)
        {
            selector = (bothnewkeys & FLAG_MOVEUP) ? 7 : 9;
        }

        _menutextm((selector == 9), 7, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 9;
        }
        if(selector > 9)
        {
            selector = 0;
        }
#endif
#endif

#if PSP
        _menutext((selector == 3), col1, 0, Tr("Screen:"));
        _menutext((selector == 3), col2, 0, displayFormat[(int)videomodes.mode].name);
        _menutext((selector == 4), col1, 1, Tr("Filters:"));
        _menutext((selector == 4), col2, 1, filterName[(int)videomodes.filter]);
        _menutext((selector == 5), col1, 2, Tr("Display:"));
        _menutext((selector == 5), col2, 2, displayName[displayMode]);
        _menutext((selector >= 6 && selector <= 9), col1, 3, Tr("Overscan:"));
        _menutext((selector >= 6 && selector <= 9), col2 + 1.5, 3, ".");
        _menutext((selector >= 6 && selector <= 9), col2 + 3.5, 3, ".");
        _menutext((selector >= 6 && selector <= 9), col2 + 5.5, 3, ".");
        _menutext((selector == 6), col2, 3, "%02d", savedata.overscan[0]);
        _menutext((selector == 7), col2 + 2, 3, "%02d", savedata.overscan[1]);
        _menutext((selector == 8), col2 + 4, 3, "%02d", savedata.overscan[2]);
        _menutext((selector == 9), col2 + 6, 3, "%02d", savedata.overscan[3]);
        _menutextm((selector == 10), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 10;
        }
        if(selector > 10)
        {
            selector = 0;
        }
#endif

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {
            dir = 0;

            if(bothnewkeys & FLAG_MOVELEFT)
            {
                dir = -1;
            }
            else if(bothnewkeys & FLAG_MOVERIGHT)
            {
                dir = 1;
            }

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                savedata.brightness += 8 * dir;
                if(savedata.brightness < -256)
                {
                    savedata.brightness = -256;
                }
                if(savedata.brightness > 256)
                {
                    savedata.brightness = 256;
                }
                vga_vwait();
                set_color_correction(savedata.gamma, savedata.brightness);
                break;
            case 1:
                savedata.gamma += 8 * dir;
                if(savedata.gamma < -256)
                {
                    savedata.gamma = -256;
                }
                if(savedata.gamma > 256)
                {
                    savedata.gamma = 256;
                }
                vga_vwait();
                set_color_correction(savedata.gamma, savedata.brightness);
                break;
            case 2:
                savedata.windowpos += dir;
                if(savedata.windowpos < -2)
                {
                    savedata.windowpos = -2;
                }
                if(savedata.windowpos > 20)
                {
                    savedata.windowpos = 20;
                }
                break;
#if SDL || PSP || WII
            case 3:
#if OPENDINGUX
                video_fullscreen_flip();
                break;
#endif

#if WII
                //video_fullscreen_flip();
                video_stretch((savedata.stretch ^= 1));
                break;
#endif

#if PSP
                if(videoMode == 0 || videoMode == 1)
                {
                    // 320x240 or 480x272
                    videomodes.mode += dir;
                    if(videomodes.mode > PSP_DISPLAY_FORMATS - 1)
                    {
                        videomodes.mode = 0;
                    }
                    if(videomodes.mode < 0)
                    {
                        videomodes.mode = PSP_DISPLAY_FORMATS - 1;
                    }
                    video_set_mode(videomodes);
                }
                break;

            case 4:
                if(videoMode == 0 || videoMode == 1)
                {
                    // 320x240 or 480x272
                    videomodes.filter += dir;
                    if(videomodes.filter > PSP_DISPLAY_FILTERS - 1)
                    {
                        videomodes.filter = 0;
                    }
                    if(videomodes.filter < 0)
                    {
                        videomodes.filter = PSP_DISPLAY_FILTERS - 1;
                    }
                    savedata.swfilter = videomodes.filter;
                    video_set_mode(videomodes);
                }
                break;

            case 5:
                displayMode += dir;
                if(displayMode > PSP_DISPLAY_MODES - 1)
                {
                    displayMode = 0;
                }
                if(displayMode < 0)
                {
                    displayMode = PSP_DISPLAY_MODES - 1;
                }
                if(displayMode)
                {
                    setGraphicsTVOverScan(savedata.overscan[0], savedata.overscan[1], savedata.overscan[2], savedata.overscan[3]);
                }
                else
                {
                    setGraphicsTVOverScan(0, 0, 0, 0);
                }
                savedata.usetv = displayMode;
                disableGraphics();
                initGraphics(savedata.usetv, videomodes.pixel);
                video_set_mode(videomodes);
                break;
            case 6:
            case 7:
            case 8:
            case 9:
                savedata.overscan[selector - 8] += dir;
                if(savedata.overscan[selector - 8] > 99)
                {
                    savedata.overscan[selector - 8] = 0;
                }
                if(savedata.overscan[selector - 8] < 0)
                {
                    savedata.overscan[selector - 8] = 99;
                }
                if(displayMode)
                {
                    setGraphicsTVOverScan(savedata.overscan[0], savedata.overscan[1], savedata.overscan[2], savedata.overscan[3]);
                    video_set_mode(videomodes);
                }
                break;
#endif
#endif


#if SDL
#if !defined(GP2X) && !defined(OPENDINGUX)
                video_fullscreen_flip();
                break;
            case 4:
                savedata.usegl = !savedata.usegl;
                video_set_mode(videomodes);
                set_color_correction(savedata.gamma, savedata.brightness);
                break;
            case 5:
#ifndef ANDROID
                if(savedata.fullscreen)
                {
                    break;
                }
                savedata.hwscale += dir * 0.25;
                if(savedata.hwscale < 0.25)
                {
                    savedata.hwscale = 0.25;
                }
                if(savedata.hwscale > 4.00)
                {
                    savedata.hwscale = 4.00;
                }
                video_set_mode(videomodes);
#else
                savedata.hwscale += dir * 0.25;
                if(savedata.hwscale < 0.0)
                {
                    savedata.hwscale = 0.0;
                }
                if(savedata.hwscale > 4.00)
                {
                    savedata.hwscale = 4.00;
                }
#endif
                break;
            case 6:
#ifndef ANDROID
                if (opengl || (!savedata.fullscreen && savedata.hwscale == 1.0))
                {
                    break;
                }
#endif
                savedata.hwfilter += dir;
                if(savedata.hwfilter < 0)
                {
                    savedata.hwfilter = 1;
                }
                if(savedata.hwfilter > 1)
                {
                    savedata.hwfilter = 0;
                }
                video_set_mode(videomodes);
				break;
            case 7:
                if(!savedata.fullscreen && savedata.hwscale < 2.0)
                {
                    break;
                }
                videomodes.filter += dir;
                if(videomodes.filter > BLITTER_MAX - 1)
                {
                    videomodes.filter = 0;
                }
                if(videomodes.filter < 0)
                {
                    videomodes.filter = BLITTER_MAX - 1;
                }
                savedata.swfilter = videomodes.filter;
                memset(pDeltaBuffer, 0x00, 1244160);
				video_set_mode(videomodes);
                break;
            case 8:
                video_stretch((savedata.stretch ^= 1));
                break;
#endif
#endif
            default:
                quit = 1;
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
    videooptionsMenu = 0;
}

functions.menu_options_input:
void menu_options_input()
{
    int quit = 0;
    int selector = 1; // 0
    int x_pos = -6;
    #if ANDROID
    int OPTIONS_NUM = 6;
    #else
    int OPTIONS_NUM = 5;
    #endif

    controloptionsMenu = 1;
    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, x_pos-1, 0, Tr("Control Options"));

        #if PSP
        if(savedata.usejoy)
        {
            _menutext((selector == 0), -4, -2, Tr("Analog Pad Enabled"));
        }
        else
        {
            _menutext((selector == 0), -4, -2, Tr("Analog Pad Disabled"));
        }
        #elif WII
        if(savedata.usejoy)
        {
            _menutext((selector == 0), -4, -2, Tr("Nunchuk Analog Enabled"));
        }
        else
        {
            _menutext((selector == 0), -4, -2, Tr("Nunchuk Analog Disabled"));
        }
        #else
        if(savedata.usejoy)
        {
            _menutext((selector == 0), x_pos, -2, Tr("GamePads Enabled"));
            if(!control_getjoyenabled())
            {
                _menutext((selector == 0), x_pos+11, -2, Tr(" - Device Not Ready"));
            }
        }
        else
        {
            _menutext((selector == 0), x_pos, -2, Tr("GamePads Disabled"));
        }
        #endif

        _menutext((selector == 1), x_pos,-1, Tr("Setup Player 1..."));
        _menutext((selector == 2), x_pos, 0, Tr("Setup Player 2..."));
        _menutext((selector == 3), x_pos, 1, Tr("Setup Player 3..."));
        _menutext((selector == 4), x_pos, 2, Tr("Setup Player 4..."));
        #if ANDROID
        if(savedata.is_touchpad_vibration_enabled)
        {
            _menutext((selector == 5), x_pos, 4, Tr("Touchpad Vibration Enabled"));
        }
        else
        {
            _menutext((selector == 5), x_pos, 4, Tr("Touchpad Vibration Disabled"));
        }
        _menutextm((selector == 6), 6, 0, Tr("Back"));
        #else
        _menutextm((selector == 5), 5, 0, Tr("Back"));
        #endif

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(selector < 0)
        {
            selector = OPTIONS_NUM;
        }
        if(selector > OPTIONS_NUM)
        {
            selector = 0;
        }
        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                control_usejoy((savedata.usejoy ^= 1));
                break;
            case 1:
                keyboard_setup(0);
                break;
            case 2:
                keyboard_setup(1);
                break;
            case 3:
                keyboard_setup(2);
                break;
            case 4:
                keyboard_setup(3);
                break;
            #if ANDROID
            case 5:
                savedata.is_touchpad_vibration_enabled ^= 1;
                break;
            #endif
            default:
                quit = (bothnewkeys & FLAG_ANYBUTTON);
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
    controloptionsMenu = 0;
}

functions.menu_options_sound:
void menu_options_sound()
{

    int quit = 0;
    int selector = 0;
    int dir;
    int col1 = -8;
    int col2 = 6;

    soundoptionsMenu = 1;
    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("Sound Options"));
        _menutext((selector == 0), col1, -2, Tr("Sound Volume:"));
        _menutext((selector == 0), col2, -2, "%i", savedata.soundvol);
        _menutext((selector == 1), col1, -1, Tr("SFX Volume:"));
        _menutext((selector == 1), col2, -1, "%i", savedata.effectvol);
        _menutext((selector == 2), col1, 0, Tr("Music Volume:"));
        _menutext((selector == 2), col2, 0, "%i", savedata.musicvol);
        _menutext((selector == 3), col1, 1, Tr("BGM:"));
        _menutext((selector == 3), col2, 1, (savedata.usemusic ? Tr("Enabled") : Tr("Disabled")));
        _menutext((selector == 4), col1, 2, Tr("Show Titles:"));
        _menutext((selector == 4), col2, 2, (savedata.showtitles ? Tr("Yes") : Tr("No")));
        _menutext((selector == 5), col1, 3, Tr("Advanced Options..."));
        _menutextm((selector == 6), 6, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(selector < 0)
        {
            selector = 6;
        }
        if(selector > 6)
        {
            selector = 0;
        }

        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {
            dir = 0;

            if(bothnewkeys & FLAG_MOVELEFT)
            {
                dir = -1;
            }
            else if(bothnewkeys & FLAG_MOVERIGHT)
            {
                dir = 1;
            }

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                savedata.soundvol += dir;
                if(savedata.soundvol < 0)
                {
                    savedata.soundvol = 0;
                }
                if(savedata.soundvol > 15)
                {
                    savedata.soundvol = 15;
                }
                SB_setvolume(SB_VOICEVOL, savedata.soundvol);
                break;
            case 1:
                savedata.effectvol += 4 * dir;
                if(savedata.effectvol < 0)
                {
                    savedata.effectvol = 0;
                }
                if(savedata.effectvol > 512)
                {
                    savedata.effectvol = 512;
                }
                break;
            case 3:
                if(!dir)
                {
                    break;
                }
                if(!savedata.usemusic)
                {
                    savedata.usemusic = 1;
                    music("data/music/remix", 1, 0);
                }
                else
                {
                    savedata.usemusic = 0;
                    sound_close_music();
                }
                break;
            case 2:
                savedata.musicvol += 4 * dir;
                if(savedata.musicvol < 0)
                {
                    savedata.musicvol = 0;
                }
                if(savedata.musicvol > 512)
                {
                    savedata.musicvol = 512;
                }
                sound_volume_music(savedata.musicvol, savedata.musicvol);
                break;
            case 4:
                savedata.showtitles = !savedata.showtitles;
                break;
            case 5:
                menu_options_soundcard();
                break;
            default:
                quit = 1;
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
    soundoptionsMenu = 0;
}

functions.menu_options_config:
void menu_options_config()     //  OX. Load from / save to default.cfg. Restore OpenBoR "factory" settings.
{
    int quit = 0;
    int selector = 0;
    int saved = 0;
    int loaded = 0;
    int restored = 0;

    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("Configuration Settings"));

        if(saved == 1)
        {
            _menutextm((selector == 0), -3, 0, Tr("Save Settings To Default.cfg%s"), Tr("  Done!"));
        }
        else
        {
            _menutextm((selector == 0), -3, 0, Tr("Save Settings To Default.cfg%s"), "");
        }

        if(loaded == 1)
        {
            _menutextm((selector == 1), -2, 0, Tr("Load Settings From Default.cfg%s"), Tr("  Done!"));
        }
        else
        {
            _menutextm((selector == 1), -2, 0, Tr("Load Settings From Default.cfg%s"), "");
        }

        if(restored == 1)
        {
            _menutextm((selector == 2), -1, 0, Tr("Restore OpenBoR Defaults%s"), Tr("  Done!"));
        }
        else
        {
            _menutextm((selector == 2), -1, 0, Tr("Restore OpenBoR Defaults%s"), "");
        }

        _menutextm((selector == 3), 6, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }

        if(selector < 0)
        {
            selector = 3;
        }
        if(selector > 3)
        {
            selector = 0;
        }

        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                saveasdefault();
                saved = 1;
                break;

            case 1:
                loadfromdefault();
                //borShutdown(2, "\nSettings Loaded From Default.cfg. Restart Required.\n\n");
                init_videomodes(0);
                if(!video_set_mode(videomodes))
                {
                    borShutdown(1, "Unable to set video mode: %d x %d!\n", videomodes.hRes, videomodes.vRes);
                }
                SB_setvolume(SB_VOICEVOL, savedata.soundvol);
                sound_volume_music(savedata.musicvol, savedata.musicvol);
                loaded = 1;
                break;
            case 2:
                clearsettings();
                //borShutdown(2, "\nSettings Loaded From Default.cfg. Restart Required.\n\n");
                init_videomodes(0);
                if(!video_set_mode(videomodes))
                {
                    borShutdown(1, "Unable to set video mode: %d x %d!\n", videomodes.hRes, videomodes.vRes);
                }
                SB_setvolume(SB_VOICEVOL, savedata.soundvol);
                sound_volume_music(savedata.musicvol, savedata.musicvol);
                restored = 1;
                break;
            default:
                quit = 1;
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
}

functions.menu_options_debug:
void menu_options_debug()
{
    #define MENU_POS_Y              -4
    #define MENU_ITEMS_MARGIN_Y     2
    #define COLUMN_1_POS_X          -11
    #define COLUMN_2_POS_X          COLUMN_1_POS_X + 14
    #define MENU_ITEM_FIRST_INDEX   0

    // Selections enumerator. All
    // selection items should be placed
    // here first.
    typedef enum
    {
        // First item can be
        // whatever we like,
        // but it must be set
        // to the MENU_ITEM_FIRST_INDEX
        // constant.
        ITEM_PERFORMANCE = MENU_ITEM_FIRST_INDEX,

        // Items between the first
        // and last can go in any
        // order.
        ITEM_POSITION,
        ITEM_FEATURES,
        ITEM_COL_ATTACK,
        ITEM_COL_BODY,
        ITEM_COL_ENTITY,
        ITEM_COL_RANGE,

        // This is the "Back"
        // selection and should
        // always be last.
        ITEM_EXIT
    } e_selections;

    int pos_y;
    int quit                = 0;
    e_selections selector   = 0;
    bothnewkeys             = 0;

    while(!quit)
    {
        // Display menu title.
        _menutextm(2, MENU_POS_Y, 0, Tr("Debug Settings"));

        // Menu items.
        // Y position is controlled by a incremented integer.
        // Integer has a base value of the Menu title Y
        // plus static offset. Below each item, this Y value
        // increments by one. We can then add or remove
        // menu items here and the on screen position will
        // take care of itself without us needing to mess
        // with a bunch of hard constants.

        // Reset menu item position Y.
        pos_y = MENU_POS_Y + MENU_ITEMS_MARGIN_Y;

        _menutext((selector == ITEM_PERFORMANCE),    COLUMN_1_POS_X, pos_y, Tr("Performance:"));
        _menutext((selector == ITEM_PERFORMANCE),    COLUMN_2_POS_X, pos_y, (savedata.debuginfo ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_POSITION),       COLUMN_1_POS_X, pos_y, Tr("Position:"));
        _menutext((selector == ITEM_POSITION),       COLUMN_2_POS_X, pos_y, (savedata.debug_position ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_FEATURES),       COLUMN_1_POS_X, pos_y, Tr("Features:"));
        _menutext((selector == ITEM_FEATURES),       COLUMN_2_POS_X, pos_y, (savedata.debug_features ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_COL_ATTACK),     COLUMN_1_POS_X, pos_y, Tr("Collision Attack:"));
        _menutext((selector == ITEM_COL_ATTACK),     COLUMN_2_POS_X, pos_y, (savedata.debug_collision_attack ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_COL_BODY),       COLUMN_1_POS_X, pos_y, Tr("Collision Body:"));
        _menutext((selector == ITEM_COL_BODY),       COLUMN_2_POS_X, pos_y, (savedata.debug_collision_body ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_COL_ENTITY),       COLUMN_1_POS_X, pos_y, Tr("Collision Entity:"));
        _menutext((selector == ITEM_COL_ENTITY),       COLUMN_2_POS_X, pos_y, (savedata.debug_collision_entity ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_COL_RANGE),      COLUMN_1_POS_X, pos_y, Tr("Range:"));
        _menutext((selector == ITEM_COL_RANGE),      COLUMN_2_POS_X, pos_y, (savedata.debug_collision_range ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        // Display exit title
        _menutextm((selector == ITEM_EXIT), pos_y + (MENU_ITEMS_MARGIN_Y), 0, Tr("Back"));

        // Run an engine update.
        update((level != NULL), 0);

        // If user presses up/down or esc, let's act accordingly.
        if(bothnewkeys & (FLAG_MOVEUP | FLAG_MOVEDOWN | FLAG_ESC))
        {
            // Play beep if available.
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            // If user presses escape, then set quit
            // flag immediately. Else wise, increment
            // or decrement selector as needed.
            if(bothnewkeys & FLAG_ESC)
            {
                quit = 1;
            }
            else if(bothnewkeys & FLAG_MOVEUP)
            {
                // If we are at the top item, loop
                // to last. Otherwise, move one up.
                if(selector <= MENU_ITEM_FIRST_INDEX)
                {
                    selector = ITEM_EXIT;
                }
                else
                {
                    --selector;
                }
            }
            else if(bothnewkeys & FLAG_MOVEDOWN)
            {
                // If we are at the last item
                // (which should be "back"), then
                // loop back to first. Otherwise
                // move one down.
                if(selector >= ITEM_EXIT)
                {
                    selector = MENU_ITEM_FIRST_INDEX;
                }
                else
                {
                    ++selector;
                }
            }
        }


        // Toggle selection value on left/right or
        // trigger button press.
        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {
            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            // This is where menu items are executed.
            switch(selector)
            {
                case ITEM_PERFORMANCE:
                    savedata.debuginfo = !savedata.debuginfo;
                    break;
                case ITEM_POSITION:
                    savedata.debug_position = !savedata.debug_position;
                    break;
                case ITEM_FEATURES:
                    savedata.debug_features = !savedata.debug_features;
                    break;
                case ITEM_COL_ATTACK:
                    savedata.debug_collision_attack = !savedata.debug_collision_attack;
                    break;
                case ITEM_COL_BODY:
                    savedata.debug_collision_body = !savedata.debug_collision_body;
                    break;
                case ITEM_COL_ENTITY:
                    savedata.debug_collision_entity = !savedata.debug_collision_entity;
                    break;
                case ITEM_COL_RANGE:
                    savedata.debug_collision_range = !savedata.debug_collision_range;
                    break;
                case ITEM_EXIT:
                    quit = 1;
            }
        }
    }
    savesettings();
    bothnewkeys = 0;

    #undef MENU_POS_Y
    #undef MENU_ITEMS_MARGIN_Y
    #undef COLUMN_1_POS_X
    #undef COLUMN_2_POS_X
    #undef MENU_ITEM_FIRST_INDEX
}

functions.menu_options_system:
void menu_options_system()
{
    #define SYS_OPT_Y_POS -4

    enum {
        SYS_OPT_LOG,
        SYS_OPT_VSDAMAGE,
        SYS_OPT_CHEATS,
        SYS_OPT_DEBUG,
        SYS_OPT_CONFIG,
        SYS_OPT_PSP_CPUSPEED,
        SYS_OPT_BACK
    };

    int quit = 0;
    int selector = 0;
    int col1 = -11;
    int col2 = col1+14;
    int ex_labels = 0;
    int RET = SYS_OPT_BACK-1;

#if PSP
    int dir = 0;
    int batteryPercentage = 0;
    int batteryLifeTime = 0;
    int externalPower = 0;
#endif

    systemoptionsMenu = 1;
    bothnewkeys = 0;
    if (nodebugoptions) ex_labels = 1;
    RET -= ex_labels;

    while(!quit)
    {
        _menutextm(2, SYS_OPT_Y_POS-2, 0, Tr("System Options"));

        _menutext(0, col1, SYS_OPT_Y_POS, Tr("Total RAM:"));
        _menutext(0, col2, SYS_OPT_Y_POS, Tr("%s KB"), commaprint(getSystemRam(KBYTES)));

        _menutext(0, col1, SYS_OPT_Y_POS+1, Tr("Used RAM:"));
        _menutext(0, col2, SYS_OPT_Y_POS+1, Tr("%s KB"), commaprint(getUsedRam(KBYTES)));

        _menutext(0, col1, SYS_OPT_Y_POS+2, Tr("Max Players:"));
        _menutext(0, col2, SYS_OPT_Y_POS+2, Tr("%i"), levelsets[current_set].maxplayers);

        _menutext((selector == SYS_OPT_LOG), col1, SYS_OPT_Y_POS+4, Tr("File Logging:"));
        _menutext((selector == SYS_OPT_LOG), col2, SYS_OPT_Y_POS+4, (savedata.uselog ? Tr("Enabled") : Tr("Disabled")));

        _menutext((selector == SYS_OPT_VSDAMAGE), col1, SYS_OPT_Y_POS+5, Tr("Versus Damage:"), 0);
        if(versusdamage == 0)
        {
            _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Disabled by Module"));
        }
        else if(versusdamage == 1)
        {
            _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Enabled by Module"));
        }
        else
        {
            if(savedata.mode)
            {
                _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Disabled"));    //Mode 1 - Players CAN'T attack each other
            }
            else
            {
                _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Enabled"));    //Mode 2 - Players CAN attack each other
            }
        }

        _menutext((selector == SYS_OPT_CHEATS), col1, SYS_OPT_Y_POS+6, Tr("Cheats:"));
        _menutext((selector == SYS_OPT_CHEATS), col2, SYS_OPT_Y_POS+6, forcecheatsoff ? Tr("Disabled by Module") : (cheats ? Tr("On") : Tr("Off")));
        if(!nodebugoptions) _menutext((selector == SYS_OPT_DEBUG), col1, SYS_OPT_Y_POS+7, Tr("Debug Settings..."));

#ifndef DC

        _menutext((selector == SYS_OPT_CONFIG-ex_labels), col1, SYS_OPT_Y_POS+8-ex_labels, Tr("Config Settings..."));

#endif

#if PSP
        externalPower = scePowerIsPowerOnline();
        _menutext((selector == SYS_OPT_PSP_CPUSPEED), col1, 4-ex_labels, Tr("CPU Speed:"));
        _menutext((selector == SYS_OPT_PSP_CPUSPEED), col2, 4-ex_labels, "%d MHz", scePowerGetCpuClockFrequency());
        if(!externalPower)
        {
            batteryPercentage = scePowerGetBatteryLifePercent();
            batteryLifeTime = scePowerGetBatteryLifeTime();
            _menutext(0, col1, 5-ex_labels, Tr("Battery:"));
            if(batteryPercentage < 0 || batteryLifeTime < 0)
            {
                _menutext(0, col2, 5-ex_labels, Tr("Calculating..."));
            }
            else
            {
                _menutext(0, col2, 5-ex_labels, "%d%% - %02d:%02d", batteryPercentage, batteryLifeTime / 60, batteryLifeTime - (batteryLifeTime / 60 * 60));
            }
        }
        else
        {
            _menutext(0, col1, 5-ex_labels, Tr("Charging:"));
            _menutext(0, col2, 5-ex_labels, Tr("%d%% AC Power"), scePowerGetBatteryLifePercent());
        }
        RET = 6-ex_labels;
#endif

        _menutextm((selector == RET), SYS_OPT_Y_POS+11-ex_labels, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;
            sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
        }

        if(selector < 0)
        {
            selector = RET;
        }
        if(selector > RET)
        {
            selector = 0;
        }

        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {

#if PSP
            dir = 0;
            if(bothnewkeys & FLAG_MOVELEFT)
            {
                dir = -1;
            }
            else if(bothnewkeys & FLAG_MOVERIGHT)
            {
                dir = 1;
            }
#endif

            sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);

                 if (selector==RET) quit = 1;
            else if (selector==SYS_OPT_LOG) savedata.uselog =  !savedata.uselog;
            else if (selector==SYS_OPT_VSDAMAGE)
            {
                if(versusdamage > 1)
                {
                    if(savedata.mode)
                    {
                        savedata.mode = 0;
                    }
                    else
                    {
                        savedata.mode = 1;
                    }
                }
            }
            else if (selector==SYS_OPT_CHEATS) cheats = !cheats;
            else if (selector==SYS_OPT_DEBUG && !nodebugoptions) menu_options_debug();
#ifndef DC
            else if (selector==SYS_OPT_CONFIG-ex_labels) menu_options_config();
#endif

#ifdef PSP
            else if (selector==SYS_OPT_PSP_CPUSPEED-ex_labels)
            {
                savedata.pspcpuspeed += dir;
                if(savedata.pspcpuspeed < 0)
                {
                    savedata.pspcpuspeed = 2;
                }
                if(savedata.pspcpuspeed > 2)
                {
                    savedata.pspcpuspeed = 0;
                }

                switch(savedata.pspcpuspeed)
                {
                case 0:
                    scePowerSetClockFrequency(222, 222, 111);
                    break;
                case 1:
                    scePowerSetClockFrequency(266, 266, 133);
                    break;
                case 2:
                    scePowerSetClockFrequency(333, 333, 166);
                    break;
                }
            }
#endif
            else quit = 1;
        }
    }
    savesettings();
    bothnewkeys = 0;
    systemoptionsMenu = 0;

    #undef SYS_OPT_Y_POS
}

functions.menu_options_video:
void menu_options_video()
{
    int quit = 0;
    int selector = 0;
    int dir;
    int col1 = -15, col2 = 1;

    videooptionsMenu = 1;
    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("Video Options"));
        _menutext((selector == 0), col1, -3, Tr("Brightness:"));
        _menutext((selector == 0), col2, -3, "%i", savedata.brightness);
        _menutext((selector == 1), col1, -2, Tr("Gamma:"));
        _menutext((selector == 1), col2, -2, "%i", savedata.gamma);
        _menutext((selector == 2), col1, -1, Tr("Window Offset:"));
        _menutext((selector == 2), col2, -1, "%i", savedata.windowpos);

#if OPENDINGUX
        _menutext((selector == 3), col1, 0, Tr("Display Mode:"));
        _menutext((selector == 3), col2, 0, savedata.fullscreen ? Tr("Full") : Tr("Window"));
        _menutextm((selector == 4), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 4;
        }
        if(selector > 4)
        {
            selector = 0;
        }
#endif

#if DC || GP2X || VITA
        _menutextm((selector == 3), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 3;
        }
        if(selector > 3)
        {
            selector = 0;
        }
#endif

#if WII
        _menutext((selector == 3), col1, 0, Tr("Display Mode:"));
        _menutext((selector == 3), col2, 0, (savedata.stretch ? Tr("Stretch to Screen") : Tr("Preserve Aspect Ratio")));
        _menutextm((selector == 4), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 4;
        }
        if(selector > 4)
        {
            selector = 0;
        }
#endif

#if SDL
#if !defined(GP2X) && !defined(OPENDINGUX)
        _menutext((selector == 3), col1, 0, Tr("Display Mode:"));
        _menutext((selector == 3), col2, 0, savedata.fullscreen ? Tr("Full") : Tr("Window"));

        _menutext((selector == 4), col1, 1, Tr("Video Backend:"));
        _menutext((selector == 4), col2, 1, (opengl ? Tr("OpenGL") : Tr("SDL")));

        _menutext((selector == 5), col1, 2, Tr("Scale:"));
#ifdef ANDROID
        if(savedata.hwscale == 0)
#else
		if(savedata.fullscreen)
#endif
        {
            _menutext((selector == 5), col2, 2, Tr("Automatic"));
        }
        else
        {
            _menutext((selector == 5), col2, 2, "%4.2fx - %ix%i", savedata.hwscale, (int)(videomodes.hRes * savedata.hwscale), (int)(videomodes.vRes * savedata.hwscale));
        }

        _menutext((selector == 6), col1, 3, Tr("Hardware Filter:"));
        {
            char *filterName;
            if (savedata.hwscale == 1.0 && !savedata.fullscreen)
                filterName = "Disabled";
            else if (opengl)
                filterName = "High Quality";
            else if (savedata.hwfilter)
                filterName = "Simple";
            else
                filterName = "Bilinear";
            _menutext((selector == 6), col2, 3, Tr(filterName));
        }

        _menutext((selector == 7), col1, 4, Tr("Software Filter:"));
        _menutext((selector == 7), col2, 4, ((savedata.hwscale >= 2.0 || savedata.fullscreen) ? Tr(GfxBlitterNames[savedata.swfilter]) : Tr("Disabled")));

        if(savedata.fullscreen)
        {
            _menutext((selector == 8), col1, 5, Tr("Fullscreen Type:"));
            _menutext((selector == 8), col2, 5, (savedata.stretch ? Tr("Stretch to Screen") : Tr("Preserve Aspect Ratio")));
        }
        else if(selector == 8)
        {
            selector = (bothnewkeys & FLAG_MOVEUP) ? 7 : 9;
        }

        _menutextm((selector == 9), 7, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 9;
        }
        if(selector > 9)
        {
            selector = 0;
        }
#endif
#endif

#if PSP
        _menutext((selector == 3), col1, 0, Tr("Screen:"));
        _menutext((selector == 3), col2, 0, displayFormat[(int)videomodes.mode].name);
        _menutext((selector == 4), col1, 1, Tr("Filters:"));
        _menutext((selector == 4), col2, 1, filterName[(int)videomodes.filter]);
        _menutext((selector == 5), col1, 2, Tr("Display:"));
        _menutext((selector == 5), col2, 2, displayName[displayMode]);
        _menutext((selector >= 6 && selector <= 9), col1, 3, Tr("Overscan:"));
        _menutext((selector >= 6 && selector <= 9), col2 + 1.5, 3, ".");
        _menutext((selector >= 6 && selector <= 9), col2 + 3.5, 3, ".");
        _menutext((selector >= 6 && selector <= 9), col2 + 5.5, 3, ".");
        _menutext((selector == 6), col2, 3, "%02d", savedata.overscan[0]);
        _menutext((selector == 7), col2 + 2, 3, "%02d", savedata.overscan[1]);
        _menutext((selector == 8), col2 + 4, 3, "%02d", savedata.overscan[2]);
        _menutext((selector == 9), col2 + 6, 3, "%02d", savedata.overscan[3]);
        _menutextm((selector == 10), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 10;
        }
        if(selector > 10)
        {
            selector = 0;
        }
#endif

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {
            dir = 0;

            if(bothnewkeys & FLAG_MOVELEFT)
            {
                dir = -1;
            }
            else if(bothnewkeys & FLAG_MOVERIGHT)
            {
                dir = 1;
            }

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                savedata.brightness += 8 * dir;
                if(savedata.brightness < -256)
                {
                    savedata.brightness = -256;
                }
                if(savedata.brightness > 256)
                {
                    savedata.brightness = 256;
                }
                vga_vwait();
                set_color_correction(savedata.gamma, savedata.brightness);
                break;
            case 1:
                savedata.gamma += 8 * dir;
                if(savedata.gamma < -256)
                {
                    savedata.gamma = -256;
                }
                if(savedata.gamma > 256)
                {
                    savedata.gamma = 256;
                }
                vga_vwait();
                set_color_correction(savedata.gamma, savedata.brightness);
                break;
            case 2:
                savedata.windowpos += dir;
                if(savedata.windowpos < -2)
                {
                    savedata.windowpos = -2;
                }
                if(savedata.windowpos > 20)
                {
                    savedata.windowpos = 20;
                }
                break;
#if SDL || PSP || WII
            case 3:
#if OPENDINGUX
                video_fullscreen_flip();
                break;
#endif

#if WII
                //video_fullscreen_flip();
                video_stretch((savedata.stretch ^= 1));
                break;
#endif

#if PSP
                if(videoMode == 0 || videoMode == 1)
                {
                    // 320x240 or 480x272
                    videomodes.mode += dir;
                    if(videomodes.mode > PSP_DISPLAY_FORMATS - 1)
                    {
                        videomodes.mode = 0;
                    }
                    if(videomodes.mode < 0)
                    {
                        videomodes.mode = PSP_DISPLAY_FORMATS - 1;
                    }
                    video_set_mode(videomodes);
                }
                break;

            case 4:
                if(videoMode == 0 || videoMode == 1)
                {
                    // 320x240 or 480x272
                    videomodes.filter += dir;
                    if(videomodes.filter > PSP_DISPLAY_FILTERS - 1)
                    {
                        videomodes.filter = 0;
                    }
                    if(videomodes.filter < 0)
                    {
                        videomodes.filter = PSP_DISPLAY_FILTERS - 1;
                    }
                    savedata.swfilter = videomodes.filter;
                    video_set_mode(videomodes);
                }
                break;

            case 5:
                displayMode += dir;
                if(displayMode > PSP_DISPLAY_MODES - 1)
                {
                    displayMode = 0;
                }
                if(displayMode < 0)
                {
                    displayMode = PSP_DISPLAY_MODES - 1;
                }
                if(displayMode)
                {
                    setGraphicsTVOverScan(savedata.overscan[0], savedata.overscan[1], savedata.overscan[2], savedata.overscan[3]);
                }
                else
                {
                    setGraphicsTVOverScan(0, 0, 0, 0);
                }
                savedata.usetv = displayMode;
                disableGraphics();
                initGraphics(savedata.usetv, videomodes.pixel);
                video_set_mode(videomodes);
                break;
            case 6:
            case 7:
            case 8:
            case 9:
                savedata.overscan[selector - 8] += dir;
                if(savedata.overscan[selector - 8] > 99)
                {
                    savedata.overscan[selector - 8] = 0;
                }
                if(savedata.overscan[selector - 8] < 0)
                {
                    savedata.overscan[selector - 8] = 99;
                }
                if(displayMode)
                {
                    setGraphicsTVOverScan(savedata.overscan[0], savedata.overscan[1], savedata.overscan[2], savedata.overscan[3]);
                    video_set_mode(videomodes);
                }
                break;
#endif
#endif


#if SDL
#if !defined(GP2X) && !defined(OPENDINGUX)
                video_fullscreen_flip();
                break;
            case 4:
                savedata.usegl = !savedata.usegl;
                video_set_mode(videomodes);
                set_color_correction(savedata.gamma, savedata.brightness);
                break;
            case 5:
#ifndef ANDROID
                if(savedata.fullscreen)
                {
                    break;
                }
                savedata.hwscale += dir * 0.25;
                if(savedata.hwscale < 0.25)
                {
                    savedata.hwscale = 0.25;
                }
                if(savedata.hwscale > 4.00)
                {
                    savedata.hwscale = 4.00;
                }
                video_set_mode(videomodes);
#else
                savedata.hwscale += dir * 0.25;
                if(savedata.hwscale < 0.0)
                {
                    savedata.hwscale = 0.0;
                }
                if(savedata.hwscale > 4.00)
                {
                    savedata.hwscale = 4.00;
                }
#endif
                break;
            case 6:
#ifndef ANDROID
                if (opengl || (!savedata.fullscreen && savedata.hwscale == 1.0))
                {
                    break;
                }
#endif
                savedata.hwfilter += dir;
                if(savedata.hwfilter < 0)
                {
                    savedata.hwfilter = 1;
                }
                if(savedata.hwfilter > 1)
                {
                    savedata.hwfilter = 0;
                }
                video_set_mode(videomodes);
				break;
            case 7:
                if(!savedata.fullscreen && savedata.hwscale < 2.0)
                {
                    break;
                }
                videomodes.filter += dir;
                if(videomodes.filter > BLITTER_MAX - 1)
                {
                    videomodes.filter = 0;
                }
                if(videomodes.filter < 0)
                {
                    videomodes.filter = BLITTER_MAX - 1;
                }
                savedata.swfilter = videomodes.filter;
                memset(pDeltaBuffer, 0x00, 1244160);
				video_set_mode(videomodes);
                break;
            case 8:
                video_stretch((savedata.stretch ^= 1));
                break;
#endif
#endif
            default:
                quit = 1;
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
    videooptionsMenu = 0;
}

functions.menu_options_input:
void menu_options_input()
{
    int quit = 0;
    int selector = 1; // 0
    int x_pos = -6;
    #if ANDROID
    int OPTIONS_NUM = 6;
    #else
    int OPTIONS_NUM = 5;
    #endif

    controloptionsMenu = 1;
    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("Control Options"));

        #if PSP
        if(savedata.usejoy)
        {
            _menutext((selector == 0), -4, -2, Tr("Analog Pad Enabled"));
        }
        else
        {
            _menutext((selector == 0), -4, -2, Tr("Analog Pad Disabled"));
        }
        #elif WII
        if(savedata.usejoy)
        {
            _menutext((selector == 0), -4, -2, Tr("Nunchuk Analog Enabled"));
        }
        else
        {
            _menutext((selector == 0), -4, -2, Tr("Nunchuk Analog Disabled"));
        }
        #else
        if(savedata.usejoy)
        {
            _menutext((selector == 0), x_pos, -2, Tr("GamePads Enabled"));
            if(!control_getjoyenabled())
            {
                _menutext((selector == 0), x_pos+11, -2, Tr(" - Device Not Ready"));
            }
        }
        else
        {
            _menutext((selector == 0), x_pos, -2, Tr("GamePads Disabled"));
        }
        #endif

        _menutext((selector == 1), x_pos,-1, Tr("Setup Player 1..."));
        _menutext((selector == 2), x_pos, 0, Tr("Setup Player 2..."));
        _menutext((selector == 3), x_pos, 1, Tr("Setup Player 3..."));
        _menutext((selector == 4), x_pos, 2, Tr("Setup Player 4..."));
        #if ANDROID
        if(savedata.is_touchpad_vibration_enabled)
        {
            _menutext((selector == 5), x_pos, 4, Tr("Touchpad Vibration Enabled"));
        }
        else
        {
            _menutext((selector == 5), x_pos, 4, Tr("Touchpad Vibration Disabled"));
        }
        _menutextm((selector == 6), 6, 0, Tr("Back"));
        #else
        _menutextm((selector == 5), 5, 0, Tr("Back"));
        #endif

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(selector < 0)
        {
            selector = OPTIONS_NUM;
        }
        if(selector > OPTIONS_NUM)
        {
            selector = 0;
        }
        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                control_usejoy((savedata.usejoy ^= 1));
                control_init(savedata.usejoy);
                break;
            case 1:
                if( bothnewkeys & FLAG_ANYBUTTON) keyboard_setup(0);
                break;
            case 2:
                if (bothnewkeys & FLAG_ANYBUTTON) keyboard_setup(1);
                break;
            case 3:
                if (bothnewkeys & FLAG_ANYBUTTON) keyboard_setup(2);
                break;
            case 4:
                if (bothnewkeys & FLAG_ANYBUTTON) keyboard_setup(3);
                break;
            #if ANDROID
            case 5:
                savedata.is_touchpad_vibration_enabled ^= 1;
                break;
            #endif
            default:
                quit = (bothnewkeys & FLAG_ANYBUTTON);
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
    controloptionsMenu = 0;
}

functions.menu_options_sound:
void menu_options_sound()
{

    int quit = 0;
    int selector = 0;
    int dir;
    int col1 = -8;
    int col2 = 6;

    soundoptionsMenu = 1;
    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("Sound Options"));
        _menutext((selector == 0), col1, -2, Tr("Sound Volume:"));
        _menutext((selector == 0), col2, -2, "%i", savedata.soundvol);
        _menutext((selector == 1), col1, -1, Tr("SFX Volume:"));
        _menutext((selector == 1), col2, -1, "%i", savedata.effectvol);
        _menutext((selector == 2), col1, 0, Tr("Music Volume:"));
        _menutext((selector == 2), col2, 0, "%i", savedata.musicvol);
        _menutext((selector == 3), col1, 1, Tr("BGM:"));
        _menutext((selector == 3), col2, 1, (savedata.usemusic ? Tr("Enabled") : Tr("Disabled")));
        _menutext((selector == 4), col1, 2, Tr("Show Titles:"));
        _menutext((selector == 4), col2, 2, (savedata.showtitles ? Tr("Yes") : Tr("No")));
        _menutext((selector == 5), col1, 3, Tr("Advanced Options..."));
        _menutextm((selector == 6), 6, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(selector < 0)
        {
            selector = 6;
        }
        if(selector > 6)
        {
            selector = 0;
        }

        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {
            dir = 0;

            if(bothnewkeys & FLAG_MOVELEFT)
            {
                dir = -1;
            }
            else if(bothnewkeys & FLAG_MOVERIGHT)
            {
                dir = 1;
            }

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                savedata.soundvol += dir;
                if(savedata.soundvol < 0)
                {
                    savedata.soundvol = 0;
                }
                if(savedata.soundvol > 15)
                {
                    savedata.soundvol = 15;
                }
                SB_setvolume(SB_VOICEVOL, savedata.soundvol);
                break;
            case 1:
                savedata.effectvol += 4 * dir;
                if(savedata.effectvol < 0)
                {
                    savedata.effectvol = 0;
                }
                if(savedata.effectvol > 512)
                {
                    savedata.effectvol = 512;
                }
                break;
            case 3:
                if(!dir)
                {
                    break;
                }
                if(!savedata.usemusic)
                {
                    savedata.usemusic = 1;
                    music("data/music/remix", 1, 0);
                }
                else
                {
                    savedata.usemusic = 0;
                    sound_close_music();
                }
                break;
            case 2:
                savedata.musicvol += 4 * dir;
                if(savedata.musicvol < 0)
                {
                    savedata.musicvol = 0;
                }
                if(savedata.musicvol > 512)
                {
                    savedata.musicvol = 512;
                }
                sound_volume_music(savedata.musicvol, savedata.musicvol);
                break;
            case 4:
                savedata.showtitles = !savedata.showtitles;
                break;
            case 5:
                if (bothnewkeys & FLAG_ANYBUTTON) menu_options_soundcard();
                break;
            default:
                quit = (bothnewkeys & FLAG_ANYBUTTON);
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
    soundoptionsMenu = 0;
}

functions.menu_options_config:
void menu_options_config()     //  OX. Load from / save to default.cfg. Restore OpenBoR "factory" settings.
{
    int quit = 0;
    int selector = 0;
    int saved = 0;
    int loaded = 0;
    int restored = 0;

    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("Configuration Settings"));

        if(saved == 1)
        {
            _menutextm((selector == 0), -3, 0, Tr("Save Settings To Default.cfg%s"), Tr("  Done!"));
        }
        else
        {
            _menutextm((selector == 0), -3, 0, Tr("Save Settings To Default.cfg%s"), "");
        }

        if(loaded == 1)
        {
            _menutextm((selector == 1), -2, 0, Tr("Load Settings From Default.cfg%s"), Tr("  Done!"));
        }
        else
        {
            _menutextm((selector == 1), -2, 0, Tr("Load Settings From Default.cfg%s"), "");
        }

        if(restored == 1)
        {
            _menutextm((selector == 2), -1, 0, Tr("Restore OpenBoR Defaults%s"), Tr("  Done!"));
        }
        else
        {
            _menutextm((selector == 2), -1, 0, Tr("Restore OpenBoR Defaults%s"), "");
        }

        _menutextm((selector == 3), 6, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }

        if(selector < 0)
        {
            selector = 3;
        }
        if(selector > 3)
        {
            selector = 0;
        }

        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {
            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            if(bothnewkeys & FLAG_ANYBUTTON)
            {
                switch(selector)
                {
                case 0:
                    saveasdefault();
                    saved = 1;
                    break;

                case 1:
                    loadfromdefault();
                    //borShutdown(2, "\nSettings Loaded From Default.cfg. Restart Required.\n\n");
                    init_videomodes(0);
                    if(!video_set_mode(videomodes))
                    {
                        borShutdown(1, "Unable to set video mode: %d x %d!\n", videomodes.hRes, videomodes.vRes);
                    }
                    SB_setvolume(SB_VOICEVOL, savedata.soundvol);
                    sound_volume_music(savedata.musicvol, savedata.musicvol);
                    loaded = 1;
                    break;
                case 2:
                    clearsettings();
                    //borShutdown(2, "\nSettings Loaded From Default.cfg. Restart Required.\n\n");
                    init_videomodes(0);
                    if(!video_set_mode(videomodes))
                    {
                        borShutdown(1, "Unable to set video mode: %d x %d!\n", videomodes.hRes, videomodes.vRes);
                    }
                    SB_setvolume(SB_VOICEVOL, savedata.soundvol);
                    sound_volume_music(savedata.musicvol, savedata.musicvol);
                    restored = 1;
                    break;
                default:
                    quit = 1;
                }
            }            
        }
    }
    savesettings();
    bothnewkeys = 0;
}

functions.menu_options_debug:
void menu_options_debug()
{
    #define MENU_POS_Y              -4
    #define MENU_ITEMS_MARGIN_Y     2
    #define COLUMN_1_POS_X          -11
    #define COLUMN_2_POS_X          COLUMN_1_POS_X + 14
    #define MENU_ITEM_FIRST_INDEX   0

    // Selections enumerator. All
    // selection items should be placed
    // here first.
    typedef enum
    {
        // First item can be
        // whatever we like,
        // but it must be set
        // to the MENU_ITEM_FIRST_INDEX
        // constant.
        ITEM_PERFORMANCE = MENU_ITEM_FIRST_INDEX,

        // Items between the first
        // and last can go in any
        // order.
        ITEM_POSITION,
        ITEM_FEATURES,
        ITEM_COL_ATTACK,
        ITEM_COL_BODY,
        ITEM_COL_RANGE,

        // This is the "Back"
        // selection and should
        // always be last.
        ITEM_EXIT
    } e_selections;

    int pos_y;
    int quit                = 0;
    e_selections selector   = 0;
    bothnewkeys             = 0;

    while(!quit)
    {
        // Display menu title.
        _menutextm(2, -5, 0, Tr("Debug Settings"));

        // Menu items.
        // Y position is controlled by a incremented integer.
        // Integer has a base value of the Menu title Y
        // plus static offset. Below each item, this Y value
        // increments by one. We can then add or remove
        // menu items here and the on screen position will
        // take care of itself without us needing to mess
        // with a bunch of hard constants.

        // Reset menu item position Y.
        pos_y = MENU_POS_Y + MENU_ITEMS_MARGIN_Y;

        _menutext((selector == ITEM_PERFORMANCE),    COLUMN_1_POS_X, pos_y, Tr("Performance:"));
        _menutext((selector == ITEM_PERFORMANCE),    COLUMN_2_POS_X, pos_y, (savedata.debuginfo ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_POSITION),       COLUMN_1_POS_X, pos_y, Tr("Position:"));
        _menutext((selector == ITEM_POSITION),       COLUMN_2_POS_X, pos_y, (savedata.debug_position ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_FEATURES),       COLUMN_1_POS_X, pos_y, Tr("Features:"));
        _menutext((selector == ITEM_FEATURES),       COLUMN_2_POS_X, pos_y, (savedata.debug_features ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_COL_ATTACK),     COLUMN_1_POS_X, pos_y, Tr("Collision Attack:"));
        _menutext((selector == ITEM_COL_ATTACK),     COLUMN_2_POS_X, pos_y, (savedata.debug_collision_attack ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_COL_BODY),       COLUMN_1_POS_X, pos_y, Tr("Collision Body:"));
        _menutext((selector == ITEM_COL_BODY),       COLUMN_2_POS_X, pos_y, (savedata.debug_collision_body ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_COL_RANGE),      COLUMN_1_POS_X, pos_y, Tr("Range:"));
        _menutext((selector == ITEM_COL_RANGE),      COLUMN_2_POS_X, pos_y, (savedata.debug_collision_range ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        // Display exit title
        _menutextm((selector == ITEM_EXIT), pos_y + (MENU_ITEMS_MARGIN_Y), 0, Tr("Back"));

        // Run an engine update.
        update((level != NULL), 0);

        // If user presses up/down or esc, let's act accordingly.
        if(bothnewkeys & (FLAG_MOVEUP | FLAG_MOVEDOWN | FLAG_ESC))
        {
            // Play beep if available.
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            // If user presses escape, then set quit
            // flag immediately. Else wise, increment
            // or decrement selector as needed.
            if(bothnewkeys & FLAG_ESC)
            {
                quit = 1;
            }
            else if(bothnewkeys & FLAG_MOVEUP)
            {
                // If we are at the top item, loop
                // to last. Otherwise, move one up.
                if(selector <= MENU_ITEM_FIRST_INDEX)
                {
                    selector = ITEM_EXIT;
                }
                else
                {
                    --selector;
                }
            }
            else if(bothnewkeys & FLAG_MOVEDOWN)
            {
                // If we are at the last item
                // (which should be "back"), then
                // loop back to first. Otherwise
                // move one down.
                if(selector >= ITEM_EXIT)
                {
                    selector = MENU_ITEM_FIRST_INDEX;
                }
                else
                {
                    ++selector;
                }
            }
        }


        // Toggle selection value on left/right or
        // trigger button press.
        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {
            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            // This is where menu items are executed.
            switch(selector)
            {
                case ITEM_PERFORMANCE:
                    savedata.debuginfo = !savedata.debuginfo;
                    break;
                case ITEM_POSITION:
                    savedata.debug_position = !savedata.debug_position;
                    break;
                case ITEM_FEATURES:
                    savedata.debug_features = !savedata.debug_features;
                    break;
                case ITEM_COL_ATTACK:
                    savedata.debug_collision_attack = !savedata.debug_collision_attack;
                    break;
                case ITEM_COL_BODY:
                    savedata.debug_collision_body = !savedata.debug_collision_body;
                    break;
                case ITEM_COL_RANGE:
                    savedata.debug_collision_range = !savedata.debug_collision_range;
                    break;
                case ITEM_EXIT:
                    quit = (bothnewkeys & FLAG_ANYBUTTON);
            }
        }
    }
    savesettings();
    bothnewkeys = 0;

    #undef MENU_POS_Y
    #undef MENU_ITEMS_MARGIN_Y
    #undef COLUMN_1_POS_X
    #undef COLUMN_2_POS_X
    #undef MENU_ITEM_FIRST_INDEX
}

functions.menu_options_system:
void menu_options_system()
{
    #define SYS_OPT_Y_POS -4

    enum {
        SYS_OPT_LOG,
        SYS_OPT_VSDAMAGE,
        SYS_OPT_CHEATS,
        SYS_OPT_DEBUG,
        SYS_OPT_CONFIG,
        SYS_OPT_PSP_CPUSPEED,
        SYS_OPT_BACK
    };

    int quit = 0;
    int selector = 0;
    int col1 = -11;
    int col2 = col1+14;
    int ex_labels = 0;
    int RET = SYS_OPT_BACK-1;

#if PSP
    int dir = 0;
    int batteryPercentage = 0;
    int batteryLifeTime = 0;
    int externalPower = 0;
#endif

    systemoptionsMenu = 1;
    bothnewkeys = 0;
    if (nodebugoptions) ex_labels = 1;
    RET -= ex_labels;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("System Options"));

        _menutext(0, col1, SYS_OPT_Y_POS, Tr("Total RAM:"));
        _menutext(0, col2, SYS_OPT_Y_POS, Tr("%s KB"), commaprint(getSystemRam(KBYTES)));

        _menutext(0, col1, SYS_OPT_Y_POS+1, Tr("Used RAM:"));
        _menutext(0, col2, SYS_OPT_Y_POS+1, Tr("%s KB"), commaprint(getUsedRam(KBYTES)));

        _menutext(0, col1, SYS_OPT_Y_POS+2, Tr("Max Players:"));
        _menutext(0, col2, SYS_OPT_Y_POS+2, Tr("%i"), levelsets[current_set].maxplayers);

        _menutext((selector == SYS_OPT_LOG), col1, SYS_OPT_Y_POS+4, Tr("File Logging:"));
        _menutext((selector == SYS_OPT_LOG), col2, SYS_OPT_Y_POS+4, (savedata.uselog ? Tr("Enabled") : Tr("Disabled")));

        _menutext((selector == SYS_OPT_VSDAMAGE), col1, SYS_OPT_Y_POS+5, Tr("Versus Damage:"), 0);
        if(versusdamage == 0)
        {
            _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Disabled by Module"));
        }
        else if(versusdamage == 1)
        {
            _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Enabled by Module"));
        }
        else
        {
            if(savedata.mode)
            {
                _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Disabled"));    //Mode 1 - Players CAN'T attack each other
            }
            else
            {
                _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Enabled"));    //Mode 2 - Players CAN attack each other
            }
        }

        _menutext((selector == SYS_OPT_CHEATS), col1, SYS_OPT_Y_POS+6, Tr("Cheats:"));
        _menutext((selector == SYS_OPT_CHEATS), col2, SYS_OPT_Y_POS+6, forcecheatsoff ? Tr("Disabled by Module") : (cheats ? Tr("On") : Tr("Off")));
        if(!nodebugoptions) _menutext((selector == SYS_OPT_DEBUG), col1, SYS_OPT_Y_POS+7, Tr("Debug Settings..."));

#ifndef DC

        _menutext((selector == SYS_OPT_CONFIG-ex_labels), col1, SYS_OPT_Y_POS+8-ex_labels, Tr("Config Settings..."));

#endif

#if PSP
        externalPower = scePowerIsPowerOnline();
        _menutext((selector == SYS_OPT_PSP_CPUSPEED), col1, 4-ex_labels, Tr("CPU Speed:"));
        _menutext((selector == SYS_OPT_PSP_CPUSPEED), col2, 4-ex_labels, "%d MHz", scePowerGetCpuClockFrequency());
        if(!externalPower)
        {
            batteryPercentage = scePowerGetBatteryLifePercent();
            batteryLifeTime = scePowerGetBatteryLifeTime();
            _menutext(0, col1, 5-ex_labels, Tr("Battery:"));
            if(batteryPercentage < 0 || batteryLifeTime < 0)
            {
                _menutext(0, col2, 5-ex_labels, Tr("Calculating..."));
            }
            else
            {
                _menutext(0, col2, 5-ex_labels, "%d%% - %02d:%02d", batteryPercentage, batteryLifeTime / 60, batteryLifeTime - (batteryLifeTime / 60 * 60));
            }
        }
        else
        {
            _menutext(0, col1, 5-ex_labels, Tr("Charging:"));
            _menutext(0, col2, 5-ex_labels, Tr("%d%% AC Power"), scePowerGetBatteryLifePercent());
        }
        RET = 6-ex_labels;
#endif

        _menutextm((selector == RET), SYS_OPT_Y_POS+11-ex_labels, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;
            sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
        }

        if(selector < 0)
        {
            selector = RET;
        }
        if(selector > RET)
        {
            selector = 0;
        }

        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {

#if PSP
            dir = 0;
            if(bothnewkeys & FLAG_MOVELEFT)
            {
                dir = -1;
            }
            else if(bothnewkeys & FLAG_MOVERIGHT)
            {
                dir = 1;
            }
#endif

            sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);

                 if (selector==RET) quit = (bothnewkeys & FLAG_ANYBUTTON);
            else if (selector==SYS_OPT_LOG) savedata.uselog =  !savedata.uselog;
            else if (selector==SYS_OPT_VSDAMAGE)
            {
                if(versusdamage > 1)
                {
                    if(savedata.mode)
                    {
                        savedata.mode = 0;
                    }
                    else
                    {
                        savedata.mode = 1;
                    }
                }
            }
            else if (selector==SYS_OPT_CHEATS) cheats = !cheats;
            else if (selector==SYS_OPT_DEBUG && !nodebugoptions && (bothnewkeys & FLAG_ANYBUTTON)) menu_options_debug();
#ifndef DC
            else if (selector==SYS_OPT_CONFIG-ex_labels && (bothnewkeys & FLAG_ANYBUTTON)) menu_options_config();
#endif

#ifdef PSP
            else if (selector==SYS_OPT_PSP_CPUSPEED-ex_labels)
            {
                savedata.pspcpuspeed += dir;
                if(savedata.pspcpuspeed < 0)
                {
                    savedata.pspcpuspeed = 2;
                }
                if(savedata.pspcpuspeed > 2)
                {
                    savedata.pspcpuspeed = 0;
                }

                switch(savedata.pspcpuspeed)
                {
                case 0:
                    scePowerSetClockFrequency(222, 222, 111);
                    break;
                case 1:
                    scePowerSetClockFrequency(266, 266, 133);
                    break;
                case 2:
                    scePowerSetClockFrequency(333, 333, 166);
                    break;
                }
            }
#endif
            else quit = (bothnewkeys & FLAG_ANYBUTTON);
        }
    }
    savesettings();
    bothnewkeys = 0;
    systemoptionsMenu = 0;

    #undef SYS_OPT_Y_POS
}

functions.menu_options_video:
void menu_options_video()
{
    int quit = 0;
    int selector = 0;
    int dir;
    int col1 = -15, col2 = 1;

    videooptionsMenu = 1;
    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("Video Options"));
        _menutext((selector == 0), col1, -3, Tr("Brightness:"));
        _menutext((selector == 0), col2, -3, "%i", savedata.brightness);
        _menutext((selector == 1), col1, -2, Tr("Gamma:"));
        _menutext((selector == 1), col2, -2, "%i", savedata.gamma);
        _menutext((selector == 2), col1, -1, Tr("Window Offset:"));
        _menutext((selector == 2), col2, -1, "%i", savedata.windowpos);

#if OPENDINGUX
        _menutext((selector == 3), col1, 0, Tr("Display Mode:"));
        _menutext((selector == 3), col2, 0, savedata.fullscreen ? Tr("Full") : Tr("Window"));
        _menutextm((selector == 4), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 4;
        }
        if(selector > 4)
        {
            selector = 0;
        }
#endif

#if DC || GP2X
        _menutextm((selector == 3), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 3;
        }
        if(selector > 3)
        {
            selector = 0;
        }
#endif

#if VITA
        _menutext((selector == 3), col1, 0, Tr("Display Mode:"));
        _menutext((selector == 3), col2, 0, (savedata.stretch ? Tr("Stretch to Screen") : Tr("Preserve Aspect Ratio")));

        _menutext((selector == 4), col1, 1, Tr("Filters:"));
        _menutext((selector == 4), col2, 1, (savedata.hwfilter ? Tr("Linear") : Tr("Point")));
        _menutext((selector == 5), col1, 2, Tr("Shader:"));
        {
            char *shaderName;
            if (savedata.shader == 1)
                shaderName = "lcd3x";
            else if (savedata.shader == 2)
                shaderName = "sharp+scan";
            else if (savedata.shader == 3)
                shaderName = "sharp";
            else if (savedata.shader == 4)
                shaderName = "advanced aa";
            else
                shaderName = "none";
            _menutext((selector == 5), col2, 2, Tr(shaderName));
        }
        _menutextm((selector == 6), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 6;
        }
        if(selector > 6)
        {
            selector = 0;
        }
#endif

#if WII
        _menutext((selector == 3), col1, 0, Tr("Display Mode:"));
        _menutext((selector == 3), col2, 0, (savedata.stretch ? Tr("Stretch to Screen") : Tr("Preserve Aspect Ratio")));
        _menutextm((selector == 4), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 4;
        }
        if(selector > 4)
        {
            selector = 0;
        }
#endif

#if SDL
#if !defined(GP2X) && !defined(OPENDINGUX)
        _menutext((selector == 3), col1, 0, Tr("Display Mode:"));
        _menutext((selector == 3), col2, 0, savedata.fullscreen ? Tr("Full") : Tr("Window"));

        _menutext((selector == 4), col1, 1, Tr("Video Backend:"));
        _menutext((selector == 4), col2, 1, (opengl ? Tr("OpenGL") : Tr("SDL")));

        _menutext((selector == 5), col1, 2, Tr("Scale:"));
#ifdef ANDROID
        if(savedata.hwscale == 0)
#else
		if(savedata.fullscreen)
#endif
        {
            _menutext((selector == 5), col2, 2, Tr("Automatic"));
        }
        else
        {
            _menutext((selector == 5), col2, 2, "%4.2fx - %ix%i", savedata.hwscale, (int)(videomodes.hRes * savedata.hwscale), (int)(videomodes.vRes * savedata.hwscale));
        }

        _menutext((selector == 6), col1, 3, Tr("Hardware Filter:"));
        {
            char *filterName;
            if (savedata.hwscale == 1.0 && !savedata.fullscreen)
                filterName = "Disabled";
            else if (opengl)
                filterName = "High Quality";
            else if (savedata.hwfilter)
                filterName = "Simple";
            else
                filterName = "Bilinear";
            _menutext((selector == 6), col2, 3, Tr(filterName));
        }

        _menutext((selector == 7), col1, 4, Tr("Software Filter:"));
        _menutext((selector == 7), col2, 4, ((savedata.hwscale >= 2.0 || savedata.fullscreen) ? Tr(GfxBlitterNames[savedata.swfilter]) : Tr("Disabled")));

        _menutext((selector == 8), col1, 5, Tr("VSync:"));
        _menutext((selector == 8), col2, 5, savedata.vsync ? "Enabled" : "Disabled");

        if(savedata.fullscreen)
        {
            _menutext((selector == 9), col1, 6, Tr("Fullscreen Type:"));
            _menutext((selector == 9), col2, 6, (savedata.stretch ? Tr("Stretch to Screen") : Tr("Preserve Aspect Ratio")));
        }
        else if(selector == 9)
        {
            selector = (bothnewkeys & FLAG_MOVEUP) ? 8 : 10;
        }

        _menutextm((selector == 10), 8, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 10;
        }
        if(selector > 10)
        {
            selector = 0;
        }
#endif
#endif

#if PSP
        _menutext((selector == 3), col1, 0, Tr("Screen:"));
        _menutext((selector == 3), col2, 0, displayFormat[(int)videomodes.mode].name);
        _menutext((selector == 4), col1, 1, Tr("Filters:"));
        _menutext((selector == 4), col2, 1, filterName[(int)videomodes.filter]);
        _menutext((selector == 5), col1, 2, Tr("Display:"));
        _menutext((selector == 5), col2, 2, displayName[displayMode]);
        _menutext((selector >= 6 && selector <= 9), col1, 3, Tr("Overscan:"));
        _menutext((selector >= 6 && selector <= 9), col2 + 1.5, 3, ".");
        _menutext((selector >= 6 && selector <= 9), col2 + 3.5, 3, ".");
        _menutext((selector >= 6 && selector <= 9), col2 + 5.5, 3, ".");
        _menutext((selector == 6), col2, 3, "%02d", savedata.overscan[0]);
        _menutext((selector == 7), col2 + 2, 3, "%02d", savedata.overscan[1]);
        _menutext((selector == 8), col2 + 4, 3, "%02d", savedata.overscan[2]);
        _menutext((selector == 9), col2 + 6, 3, "%02d", savedata.overscan[3]);
        _menutextm((selector == 10), 6, 0, Tr("Back"));
        if(selector < 0)
        {
            selector = 10;
        }
        if(selector > 10)
        {
            selector = 0;
        }
#endif

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {
            dir = 0;

            if(bothnewkeys & FLAG_MOVELEFT)
            {
                dir = -1;
            }
            else if(bothnewkeys & FLAG_MOVERIGHT)
            {
                dir = 1;
            }

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                savedata.brightness += 8 * dir;
                if(savedata.brightness < -256)
                {
                    savedata.brightness = -256;
                }
                if(savedata.brightness > 256)
                {
                    savedata.brightness = 256;
                }
                vga_vwait();
                set_color_correction(savedata.gamma, savedata.brightness);
                break;
            case 1:
                savedata.gamma += 8 * dir;
                if(savedata.gamma < -256)
                {
                    savedata.gamma = -256;
                }
                if(savedata.gamma > 256)
                {
                    savedata.gamma = 256;
                }
                vga_vwait();
                set_color_correction(savedata.gamma, savedata.brightness);
                break;
            case 2:
                savedata.windowpos += dir;
                if(savedata.windowpos < -2)
                {
                    savedata.windowpos = -2;
                }
                if(savedata.windowpos > 20)
                {
                    savedata.windowpos = 20;
                }
                break;

#if VITA
            case 3:
                savedata.stretch += dir;
                if(savedata.stretch > 1)
                {
                    savedata.stretch = 0;
                }
                if(savedata.stretch < 0)
                {
                    savedata.stretch = 1;
                }
                break;
            case 4:
                savedata.hwfilter += dir;
                if(savedata.hwfilter > 1)
                {
                    savedata.hwfilter = 0;
                }
                if(savedata.hwfilter < 0)
                {
                    savedata.hwfilter = 1;
                }
                break;
            case 5:
                savedata.shader += dir;
                if(savedata.shader > 4)
                {
                    savedata.shader = 0;
                }
                if(savedata.shader < 0)
                {
                    savedata.shader = 4;
                }
                break;
#endif

#if SDL || PSP || WII
            case 3:
#if OPENDINGUX
                video_fullscreen_flip();
                break;
#endif

#if WII
                //video_fullscreen_flip();
                video_stretch((savedata.stretch ^= 1));
                break;
#endif

#if PSP
                if(videoMode == 0 || videoMode == 1)
                {
                    // 320x240 or 480x272
                    videomodes.mode += dir;
                    if(videomodes.mode > PSP_DISPLAY_FORMATS - 1)
                    {
                        videomodes.mode = 0;
                    }
                    if(videomodes.mode < 0)
                    {
                        videomodes.mode = PSP_DISPLAY_FORMATS - 1;
                    }
                    video_set_mode(videomodes);
                }
                break;

            case 4:
                if(videoMode == 0 || videoMode == 1)
                {
                    // 320x240 or 480x272
                    videomodes.filter += dir;
                    if(videomodes.filter > PSP_DISPLAY_FILTERS - 1)
                    {
                        videomodes.filter = 0;
                    }
                    if(videomodes.filter < 0)
                    {
                        videomodes.filter = PSP_DISPLAY_FILTERS - 1;
                    }
                    savedata.swfilter = videomodes.filter;
                    video_set_mode(videomodes);
                }
                break;

            case 5:
                displayMode += dir;
                if(displayMode > PSP_DISPLAY_MODES - 1)
                {
                    displayMode = 0;
                }
                if(displayMode < 0)
                {
                    displayMode = PSP_DISPLAY_MODES - 1;
                }
                if(displayMode)
                {
                    setGraphicsTVOverScan(savedata.overscan[0], savedata.overscan[1], savedata.overscan[2], savedata.overscan[3]);
                }
                else
                {
                    setGraphicsTVOverScan(0, 0, 0, 0);
                }
                savedata.usetv = displayMode;
                disableGraphics();
                initGraphics(savedata.usetv, videomodes.pixel);
                video_set_mode(videomodes);
                break;
            case 6:
            case 7:
            case 8:
            case 9:
                savedata.overscan[selector - 8] += dir;
                if(savedata.overscan[selector - 8] > 99)
                {
                    savedata.overscan[selector - 8] = 0;
                }
                if(savedata.overscan[selector - 8] < 0)
                {
                    savedata.overscan[selector - 8] = 99;
                }
                if(displayMode)
                {
                    setGraphicsTVOverScan(savedata.overscan[0], savedata.overscan[1], savedata.overscan[2], savedata.overscan[3]);
                    video_set_mode(videomodes);
                }
                break;
#endif
#endif


#if SDL
#if !defined(GP2X) && !defined(OPENDINGUX)
                video_fullscreen_flip();
                break;
            case 4:
                savedata.usegl = !savedata.usegl;
                video_set_mode(videomodes);
                set_color_correction(savedata.gamma, savedata.brightness);
                break;
            case 5:
#ifndef ANDROID
                if(savedata.fullscreen)
                {
                    break;
                }
                savedata.hwscale += dir * 0.25;
                if(savedata.hwscale < 0.25)
                {
                    savedata.hwscale = 0.25;
                }
                if(savedata.hwscale > 4.00)
                {
                    savedata.hwscale = 4.00;
                }
                video_set_mode(videomodes);
#else
                savedata.hwscale += dir * 0.25;
                if(savedata.hwscale < 0.0)
                {
                    savedata.hwscale = 0.0;
                }
                if(savedata.hwscale > 4.00)
                {
                    savedata.hwscale = 4.00;
                }
#endif
                break;
            case 6:
#ifndef ANDROID
                if (opengl || (!savedata.fullscreen && savedata.hwscale == 1.0))
                {
                    break;
                }
#endif
                savedata.hwfilter += dir;
                if(savedata.hwfilter < 0)
                {
                    savedata.hwfilter = 1;
                }
                if(savedata.hwfilter > 1)
                {
                    savedata.hwfilter = 0;
                }
                video_set_mode(videomodes);
				break;
            case 7:
                if(!savedata.fullscreen && savedata.hwscale < 2.0)
                {
                    break;
                }
                videomodes.filter += dir;
                if(videomodes.filter > BLITTER_MAX - 1)
                {
                    videomodes.filter = 0;
                }
                if(videomodes.filter < 0)
                {
                    videomodes.filter = BLITTER_MAX - 1;
                }
                savedata.swfilter = videomodes.filter;
                memset(pDeltaBuffer, 0x00, 1244160);
				video_set_mode(videomodes);
                break;
            case 8:
                savedata.vsync = !savedata.vsync;
                video_set_mode(videomodes);
                break;
            case 9:
                video_stretch((savedata.stretch ^= 1));
                break;
#endif
#endif
            default:
                quit = (bothnewkeys & FLAG_ANYBUTTON);
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
    videooptionsMenu = 0;
}

functions.menu_options_input:
void menu_options_input()
{
    int quit = 0;
    int selector = 1; // 0
    int x_pos = -6;
    #if ANDROID
    int OPTIONS_NUM = 6;
    #else
    int OPTIONS_NUM = 5;
    #endif

    controloptionsMenu = 1;
    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, x_pos-1, 0, Tr("Control Options"));

        #if PSP
        if(savedata.usejoy)
        {
            _menutext((selector == 0), -4, -2, Tr("Analog Pad Enabled"));
        }
        else
        {
            _menutext((selector == 0), -4, -2, Tr("Analog Pad Disabled"));
        }
        #elif WII
        if(savedata.usejoy)
        {
            _menutext((selector == 0), -4, -2, Tr("Nunchuk Analog Enabled"));
        }
        else
        {
            _menutext((selector == 0), -4, -2, Tr("Nunchuk Analog Disabled"));
        }
        #else
        if(savedata.usejoy)
        {
            _menutext((selector == 0), x_pos, -2, Tr("GamePads Enabled"));
            if(!control_getjoyenabled())
            {
                _menutext((selector == 0), x_pos+11, -2, Tr(" - Device Not Ready"));
            }
        }
        else
        {
            _menutext((selector == 0), x_pos, -2, Tr("GamePads Disabled"));
        }
        #endif

        _menutext((selector == 1), x_pos,-1, Tr("Setup Player 1..."));
        _menutext((selector == 2), x_pos, 0, Tr("Setup Player 2..."));
        _menutext((selector == 3), x_pos, 1, Tr("Setup Player 3..."));
        _menutext((selector == 4), x_pos, 2, Tr("Setup Player 4..."));
        #if ANDROID
        if(savedata.is_touchpad_vibration_enabled)
        {
            _menutext((selector == 5), x_pos, 4, Tr("Touchpad Vibration Enabled"));
        }
        else
        {
            _menutext((selector == 5), x_pos, 4, Tr("Touchpad Vibration Disabled"));
        }
        _menutextm((selector == 6), 6, 0, Tr("Back"));
        #else
        _menutextm((selector == 5), 5, 0, Tr("Back"));
        #endif

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(selector < 0)
        {
            selector = OPTIONS_NUM;
        }
        if(selector > OPTIONS_NUM)
        {
            selector = 0;
        }
        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                control_usejoy((savedata.usejoy ^= 1));
                break;
            case 1:
                keyboard_setup(0);
                break;
            case 2:
                keyboard_setup(1);
                break;
            case 3:
                keyboard_setup(2);
                break;
            case 4:
                keyboard_setup(3);
                break;
            #if ANDROID
            case 5:
                savedata.is_touchpad_vibration_enabled ^= 1;
                break;
            #endif
            default:
                quit = (bothnewkeys & FLAG_ANYBUTTON);
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
    controloptionsMenu = 0;
}

functions.menu_options_sound:
void menu_options_sound()
{

    int quit = 0;
    int selector = 0;
    int dir;
    int col1 = -8;
    int col2 = 6;

    soundoptionsMenu = 1;
    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("Sound Options"));
        _menutext((selector == 0), col1, -2, Tr("Sound Volume:"));
        _menutext((selector == 0), col2, -2, "%i", savedata.soundvol);
        _menutext((selector == 1), col1, -1, Tr("SFX Volume:"));
        _menutext((selector == 1), col2, -1, "%i", savedata.effectvol);
        _menutext((selector == 2), col1, 0, Tr("Music Volume:"));
        _menutext((selector == 2), col2, 0, "%i", savedata.musicvol);
        _menutext((selector == 3), col1, 1, Tr("BGM:"));
        _menutext((selector == 3), col2, 1, (savedata.usemusic ? Tr("Enabled") : Tr("Disabled")));
        _menutext((selector == 4), col1, 2, Tr("Show Titles:"));
        _menutext((selector == 4), col2, 2, (savedata.showtitles ? Tr("Yes") : Tr("No")));
        _menutext((selector == 5), col1, 3, Tr("Advanced Options..."));
        _menutextm((selector == 6), 6, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(selector < 0)
        {
            selector = 6;
        }
        if(selector > 6)
        {
            selector = 0;
        }

        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {
            dir = 0;

            if(bothnewkeys & FLAG_MOVELEFT)
            {
                dir = -1;
            }
            else if(bothnewkeys & FLAG_MOVERIGHT)
            {
                dir = 1;
            }

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                savedata.soundvol += dir;
                if(savedata.soundvol < 0)
                {
                    savedata.soundvol = 0;
                }
                if(savedata.soundvol > 15)
                {
                    savedata.soundvol = 15;
                }
                SB_setvolume(SB_VOICEVOL, savedata.soundvol);
                break;
            case 1:
                savedata.effectvol += 4 * dir;
                if(savedata.effectvol < 0)
                {
                    savedata.effectvol = 0;
                }
                if(savedata.effectvol > 512)
                {
                    savedata.effectvol = 512;
                }
                break;
            case 3:
                if(!dir)
                {
                    break;
                }
                if(!savedata.usemusic)
                {
                    savedata.usemusic = 1;
                    music("data/music/remix", 1, 0);
                }
                else
                {
                    savedata.usemusic = 0;
                    sound_close_music();
                }
                break;
            case 2:
                savedata.musicvol += 4 * dir;
                if(savedata.musicvol < 0)
                {
                    savedata.musicvol = 0;
                }
                if(savedata.musicvol > 512)
                {
                    savedata.musicvol = 512;
                }
                sound_volume_music(savedata.musicvol, savedata.musicvol);
                break;
            case 4:
                savedata.showtitles = !savedata.showtitles;
                break;
            case 5:
                menu_options_soundcard();
                break;
            default:
                quit = 1;
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
    soundoptionsMenu = 0;
}

functions.menu_options_config:
void menu_options_config()     //  OX. Load from / save to default.cfg. Restore OpenBoR "factory" settings.
{
    int quit = 0;
    int selector = 0;
    int saved = 0;
    int loaded = 0;
    int restored = 0;

    bothnewkeys = 0;

    while(!quit)
    {
        _menutextm(2, -5, 0, Tr("Configuration Settings"));

        if(saved == 1)
        {
            _menutextm((selector == 0), -3, 0, Tr("Save Settings To Default.cfg%s"), Tr("  Done!"));
        }
        else
        {
            _menutextm((selector == 0), -3, 0, Tr("Save Settings To Default.cfg%s"), "");
        }

        if(loaded == 1)
        {
            _menutextm((selector == 1), -2, 0, Tr("Load Settings From Default.cfg%s"), Tr("  Done!"));
        }
        else
        {
            _menutextm((selector == 1), -2, 0, Tr("Load Settings From Default.cfg%s"), "");
        }

        if(restored == 1)
        {
            _menutextm((selector == 2), -1, 0, Tr("Restore OpenBoR Defaults%s"), Tr("  Done!"));
        }
        else
        {
            _menutextm((selector == 2), -1, 0, Tr("Restore OpenBoR Defaults%s"), "");
        }

        _menutextm((selector == 3), 6, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }

        if(selector < 0)
        {
            selector = 3;
        }
        if(selector > 3)
        {
            selector = 0;
        }

        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                saveasdefault();
                saved = 1;
                break;

            case 1:
                loadfromdefault();
                //borShutdown(2, "\nSettings Loaded From Default.cfg. Restart Required.\n\n");
                init_videomodes(0);
                if(!video_set_mode(videomodes))
                {
                    borShutdown(1, "Unable to set video mode: %d x %d!\n", videomodes.hRes, videomodes.vRes);
                }
                SB_setvolume(SB_VOICEVOL, savedata.soundvol);
                sound_volume_music(savedata.musicvol, savedata.musicvol);
                loaded = 1;
                break;
            case 2:
                clearsettings();
                //borShutdown(2, "\nSettings Loaded From Default.cfg. Restart Required.\n\n");
                init_videomodes(0);
                if(!video_set_mode(videomodes))
                {
                    borShutdown(1, "Unable to set video mode: %d x %d!\n", videomodes.hRes, videomodes.vRes);
                }
                SB_setvolume(SB_VOICEVOL, savedata.soundvol);
                sound_volume_music(savedata.musicvol, savedata.musicvol);
                restored = 1;
                break;
            default:
                quit = 1;
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
}

functions.menu_options_debug:
void menu_options_debug()
{
    #define MENU_POS_Y              -4
    #define MENU_ITEMS_MARGIN_Y     2
    #define COLUMN_1_POS_X          -11
    #define COLUMN_2_POS_X          COLUMN_1_POS_X + 14
    #define MENU_ITEM_FIRST_INDEX   0

    // Selections enumerator. All
    // selection items should be placed
    // here first.
    typedef enum
    {
        // First item can be
        // whatever we like,
        // but it must be set
        // to the MENU_ITEM_FIRST_INDEX
        // constant.
        ITEM_PERFORMANCE = MENU_ITEM_FIRST_INDEX,

        // Items between the first
        // and last can go in any
        // order.
        ITEM_POSITION,
        ITEM_FEATURES,
        ITEM_COL_ATTACK,
        ITEM_COL_BODY,
        ITEM_COL_ENTITY,
        ITEM_COL_RANGE,

        // This is the "Back"
        // selection and should
        // always be last.
        ITEM_EXIT
    } e_selections;

    int pos_y;
    int quit                = 0;
    e_selections selector   = 0;
    bothnewkeys             = 0;

    while(!quit)
    {
        // Display menu title.
        _menutextm(2, MENU_POS_Y, 0, Tr("Debug Settings"));

        // Menu items.
        // Y position is controlled by a incremented integer.
        // Integer has a base value of the Menu title Y
        // plus static offset. Below each item, this Y value
        // increments by one. We can then add or remove
        // menu items here and the on screen position will
        // take care of itself without us needing to mess
        // with a bunch of hard constants.

        // Reset menu item position Y.
        pos_y = MENU_POS_Y + MENU_ITEMS_MARGIN_Y;

        _menutext((selector == ITEM_PERFORMANCE),    COLUMN_1_POS_X, pos_y, Tr("Performance:"));
        _menutext((selector == ITEM_PERFORMANCE),    COLUMN_2_POS_X, pos_y, (savedata.debuginfo ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_POSITION),       COLUMN_1_POS_X, pos_y, Tr("Position:"));
        _menutext((selector == ITEM_POSITION),       COLUMN_2_POS_X, pos_y, (savedata.debug_position ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_FEATURES),       COLUMN_1_POS_X, pos_y, Tr("Features:"));
        _menutext((selector == ITEM_FEATURES),       COLUMN_2_POS_X, pos_y, (savedata.debug_features ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_COL_ATTACK),     COLUMN_1_POS_X, pos_y, Tr("Collision Attack:"));
        _menutext((selector == ITEM_COL_ATTACK),     COLUMN_2_POS_X, pos_y, (savedata.debug_collision_attack ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        _menutext((selector == ITEM_COL_BODY),       COLUMN_1_POS_X, pos_y, Tr("Collision Body:"));
        _menutext((selector == ITEM_COL_BODY),       COLUMN_2_POS_X, pos_y, (savedata.debug_collision_body ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        if(obor_profile_build != 6330)
        {
        _menutext((selector == ITEM_COL_ENTITY),       COLUMN_1_POS_X, pos_y, Tr("Collision Entity:"));
        _menutext((selector == ITEM_COL_ENTITY),       COLUMN_2_POS_X, pos_y, (savedata.debug_collision_entity ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        }

        _menutext((selector == ITEM_COL_RANGE),      COLUMN_1_POS_X, pos_y, Tr("Range:"));
        _menutext((selector == ITEM_COL_RANGE),      COLUMN_2_POS_X, pos_y, (savedata.debug_collision_range ? Tr("Enabled") : Tr("Disabled")));
        pos_y++;

        // Display exit title
        _menutextm((selector == ITEM_EXIT), pos_y + (MENU_ITEMS_MARGIN_Y), 0, Tr("Back"));

        // Run an engine update.
        update((level != NULL), 0);

        // If user presses up/down or esc, let's act accordingly.
        if(bothnewkeys & (FLAG_MOVEUP | FLAG_MOVEDOWN | FLAG_ESC))
        {
            // Play beep if available.
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            // If user presses escape, then set quit
            // flag immediately. Else wise, increment
            // or decrement selector as needed.
            if(bothnewkeys & FLAG_ESC)
            {
                quit = 1;
            }
            else if(bothnewkeys & FLAG_MOVEUP)
            {
                // If we are at the top item, loop
                // to last. Otherwise, move one up.
                if(selector <= MENU_ITEM_FIRST_INDEX)
                {
                    selector = ITEM_EXIT;
                }
                else
                {
                    --selector;
                }
            }
            else if(bothnewkeys & FLAG_MOVEDOWN)
            {
                // If we are at the last item
                // (which should be "back"), then
                // loop back to first. Otherwise
                // move one down.
                if(selector >= ITEM_EXIT)
                {
                    selector = MENU_ITEM_FIRST_INDEX;
                }
                else
                {
                    ++selector;
                }
            }
        }


        if(obor_profile_build == 6330 && selector == ITEM_COL_ENTITY)
            selector += (bothnewkeys & FLAG_MOVEUP) ? -1 : 1;

        // Toggle selection value on left/right or
        // trigger button press.
        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {
            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            // This is where menu items are executed.
            switch(selector)
            {
                case ITEM_PERFORMANCE:
                    savedata.debuginfo = !savedata.debuginfo;
                    break;
                case ITEM_POSITION:
                    savedata.debug_position = !savedata.debug_position;
                    break;
                case ITEM_FEATURES:
                    savedata.debug_features = !savedata.debug_features;
                    break;
                case ITEM_COL_ATTACK:
                    savedata.debug_collision_attack = !savedata.debug_collision_attack;
                    break;
                case ITEM_COL_BODY:
                    savedata.debug_collision_body = !savedata.debug_collision_body;
                    break;
                case ITEM_COL_ENTITY:
                    savedata.debug_collision_entity = !savedata.debug_collision_entity;
                    break;
                case ITEM_COL_RANGE:
                    savedata.debug_collision_range = !savedata.debug_collision_range;
                    break;
                case ITEM_EXIT:
                    quit = 1;
            }
        }
    }
    savesettings();
    bothnewkeys = 0;

    #undef MENU_POS_Y
    #undef MENU_ITEMS_MARGIN_Y
    #undef COLUMN_1_POS_X
    #undef COLUMN_2_POS_X
    #undef MENU_ITEM_FIRST_INDEX
}

functions.menu_options_system:
void menu_options_system()
{
    #define SYS_OPT_Y_POS -4

    enum {
        SYS_OPT_LOG,
        SYS_OPT_VSDAMAGE,
        SYS_OPT_CHEATS,
        SYS_OPT_DEBUG,
        SYS_OPT_CONFIG,
        SYS_OPT_PSP_CPUSPEED,
        SYS_OPT_BACK
    };

    int quit = 0;
    int selector = 0;
    int col1 = -11;
    int col2 = col1+14;
    int ex_labels = 0;
    int RET = SYS_OPT_BACK-1;

#if PSP
    int dir = 0;
    int batteryPercentage = 0;
    int batteryLifeTime = 0;
    int externalPower = 0;
#endif

    systemoptionsMenu = 1;
    bothnewkeys = 0;
    if (nodebugoptions) ex_labels = 1;
    RET -= ex_labels;

    while(!quit)
    {
        _menutextm(2, SYS_OPT_Y_POS-2, 0, Tr("System Options"));

        _menutext(0, col1, SYS_OPT_Y_POS, Tr("Total RAM:"));
        _menutext(0, col2, SYS_OPT_Y_POS, Tr("%s KB"), commaprint(getSystemRam(KBYTES)));

        _menutext(0, col1, SYS_OPT_Y_POS+1, Tr("Used RAM:"));
        _menutext(0, col2, SYS_OPT_Y_POS+1, Tr("%s KB"), commaprint(getUsedRam(KBYTES)));

        _menutext(0, col1, SYS_OPT_Y_POS+2, Tr("Max Players:"));
        _menutext(0, col2, SYS_OPT_Y_POS+2, Tr("%i"), levelsets[current_set].maxplayers);

        _menutext((selector == SYS_OPT_LOG), col1, SYS_OPT_Y_POS+4, Tr("File Logging:"));
        _menutext((selector == SYS_OPT_LOG), col2, SYS_OPT_Y_POS+4, (savedata.uselog ? Tr("Enabled") : Tr("Disabled")));

        _menutext((selector == SYS_OPT_VSDAMAGE), col1, SYS_OPT_Y_POS+5, Tr("Versus Damage:"), 0);
        if(versusdamage == 0)
        {
            _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Disabled by Module"));
        }
        else if(versusdamage == 1)
        {
            _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Enabled by Module"));
        }
        else
        {
            if(savedata.mode)
            {
                _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Disabled"));    //Mode 1 - Players CAN'T attack each other
            }
            else
            {
                _menutext((selector == SYS_OPT_VSDAMAGE), col2, SYS_OPT_Y_POS+5, Tr("Enabled"));    //Mode 2 - Players CAN attack each other
            }
        }

        _menutext((selector == SYS_OPT_CHEATS), col1, SYS_OPT_Y_POS+6, Tr("Cheats:"));
        _menutext((selector == SYS_OPT_CHEATS), col2, SYS_OPT_Y_POS+6, forcecheatsoff ? Tr("Disabled by Module") : (cheats ? Tr("On") : Tr("Off")));
        if(!nodebugoptions) _menutext((selector == SYS_OPT_DEBUG), col1, SYS_OPT_Y_POS+7, Tr("Debug Settings..."));

#ifndef DC

        _menutext((selector == SYS_OPT_CONFIG-ex_labels), col1, SYS_OPT_Y_POS+8-ex_labels, Tr("Config Settings..."));

#endif

#if PSP
        externalPower = scePowerIsPowerOnline();
        _menutext((selector == SYS_OPT_PSP_CPUSPEED), col1, 4-ex_labels, Tr("CPU Speed:"));
        _menutext((selector == SYS_OPT_PSP_CPUSPEED), col2, 4-ex_labels, "%d MHz", scePowerGetCpuClockFrequency());
        if(!externalPower)
        {
            batteryPercentage = scePowerGetBatteryLifePercent();
            batteryLifeTime = scePowerGetBatteryLifeTime();
            _menutext(0, col1, 5-ex_labels, Tr("Battery:"));
            if(batteryPercentage < 0 || batteryLifeTime < 0)
            {
                _menutext(0, col2, 5-ex_labels, Tr("Calculating..."));
            }
            else
            {
                _menutext(0, col2, 5-ex_labels, "%d%% - %02d:%02d", batteryPercentage, batteryLifeTime / 60, batteryLifeTime - (batteryLifeTime / 60 * 60));
            }
        }
        else
        {
            _menutext(0, col1, 5-ex_labels, Tr("Charging:"));
            _menutext(0, col2, 5-ex_labels, Tr("%d%% AC Power"), scePowerGetBatteryLifePercent());
        }
        RET = 6-ex_labels;
#endif

        _menutextm((selector == RET), SYS_OPT_Y_POS+11-ex_labels, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;
            sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
        }

        if(selector < 0)
        {
            selector = RET;
        }
        if(selector > RET)
        {
            selector = 0;
        }

        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {

#if PSP
            dir = 0;
            if(bothnewkeys & FLAG_MOVELEFT)
            {
                dir = -1;
            }
            else if(bothnewkeys & FLAG_MOVERIGHT)
            {
                dir = 1;
            }
#endif

            sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);

                 if (selector==RET) quit = 1;
            else if (selector==SYS_OPT_LOG) savedata.uselog =  !savedata.uselog;
            else if (selector==SYS_OPT_VSDAMAGE)
            {
                if(versusdamage > 1)
                {
                    if(savedata.mode)
                    {
                        savedata.mode = 0;
                    }
                    else
                    {
                        savedata.mode = 1;
                    }
                }
            }
            else if (selector==SYS_OPT_CHEATS) cheats = !cheats;
            else if (selector==SYS_OPT_DEBUG && !nodebugoptions) menu_options_debug();
#ifndef DC
            else if (selector==SYS_OPT_CONFIG-ex_labels) menu_options_config();
#endif

#ifdef PSP
            else if (selector==SYS_OPT_PSP_CPUSPEED-ex_labels)
            {
                savedata.pspcpuspeed += dir;
                if(savedata.pspcpuspeed < 0)
                {
                    savedata.pspcpuspeed = 2;
                }
                if(savedata.pspcpuspeed > 2)
                {
                    savedata.pspcpuspeed = 0;
                }

                switch(savedata.pspcpuspeed)
                {
                case 0:
                    scePowerSetClockFrequency(222, 222, 111);
                    break;
                case 1:
                    scePowerSetClockFrequency(266, 266, 133);
                    break;
                case 2:
                    scePowerSetClockFrequency(333, 333, 166);
                    break;
                }
            }
#endif
            else quit = 1;
        }
    }
    savesettings();
    bothnewkeys = 0;
    systemoptionsMenu = 0;

    #undef SYS_OPT_Y_POS
}

