            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            switch(selector)
            {
            case 0:
                savedata.brightness += 8 * dir;
                if(savedata.brightness < -256)
                {
                    savedata.brightness = -256;
                }
                if(savedata.brightness > 256)
                {
                    savedata.brightness = 256;
                }
                vga_vwait();
                set_color_correction(savedata.gamma, savedata.brightness);
                break;
            case 1:
                savedata.gamma += 8 * dir;
                if(savedata.gamma < -256)
                {
                    savedata.gamma = -256;
                }
                if(savedata.gamma > 256)
                {
                    savedata.gamma = 256;
                }
                vga_vwait();
                set_color_correction(savedata.gamma, savedata.brightness);
                break;
            case 2:
                savedata.windowpos += dir;
                if(savedata.windowpos < -2)
                {
                    savedata.windowpos = -2;
                }
                if(savedata.windowpos > 20)
                {
                    savedata.windowpos = 20;
                }
                break;
#if SDL || PSP || WII
            case 3:
#if OPENDINGUX
                video_fullscreen_flip();
                break;
#endif

#if WII
                //video_fullscreen_flip();
                video_stretch((savedata.stretch ^= 1));
                break;
#endif

#if PSP
                if(videoMode == 0 || videoMode == 1)
                {
                    // 320x240 or 480x272
                    videomodes.mode += dir;
                    if(videomodes.mode > PSP_DISPLAY_FORMATS - 1)
                    {
                        videomodes.mode = 0;
                    }
                    if(videomodes.mode < 0)
                    {
                        videomodes.mode = PSP_DISPLAY_FORMATS - 1;
                    }
                    video_set_mode(videomodes);
                }
                break;

            case 4:
                if(videoMode == 0 || videoMode == 1)
                {
                    // 320x240 or 480x272
                    videomodes.filter += dir;
                    if(videomodes.filter > PSP_DISPLAY_FILTERS - 1)
                    {
                        videomodes.filter = 0;
                    }
                    if(videomodes.filter < 0)
                    {
                        videomodes.filter = PSP_DISPLAY_FILTERS - 1;
                    }
                    savedata.swfilter = videomodes.filter;
                    video_set_mode(videomodes);
                }
                break;

            case 5:
                displayMode += dir;
                if(displayMode > PSP_DISPLAY_MODES - 1)
                {
                    displayMode = 0;
                }
                if(displayMode < 0)
                {
                    displayMode = PSP_DISPLAY_MODES - 1;
                }
                if(displayMode)
                {
                    setGraphicsTVOverScan(savedata.overscan[0], savedata.overscan[1], savedata.overscan[2], savedata.overscan[3]);
                }
                else
                {
                    setGraphicsTVOverScan(0, 0, 0, 0);
                }
                savedata.usetv = displayMode;
                disableGraphics();
                initGraphics(savedata.usetv, videomodes.pixel);
                video_set_mode(videomodes);
                break;
            case 6:
            case 7:
            case 8:
            case 9:
                savedata.overscan[selector - 8] += dir;
                if(savedata.overscan[selector - 8] > 99)
                {
                    savedata.overscan[selector - 8] = 0;
                }
                if(savedata.overscan[selector - 8] < 0)
                {
                    savedata.overscan[selector - 8] = 99;
                }
                if(displayMode)
                {
                    setGraphicsTVOverScan(savedata.overscan[0], savedata.overscan[1], savedata.overscan[2], savedata.overscan[3]);
                    video_set_mode(videomodes);
                }
                break;
#endif
#endif


#if SDL
#if !defined(GP2X) && !defined(OPENDINGUX)
                video_fullscreen_flip();
                break;
            case 4:
                savedata.usegl = !savedata.usegl;
                video_set_mode(videomodes);
                set_color_correction(savedata.gamma, savedata.brightness);
                break;
            case 5:
#ifndef ANDROID
                if(savedata.fullscreen)
                {
                    break;
                }
                savedata.hwscale += dir * 0.25;
                if(savedata.hwscale < 0.25)
                {
                    savedata.hwscale = 0.25;
                }
                if(savedata.hwscale > 4.00)
                {
                    savedata.hwscale = 4.00;
                }
                video_set_mode(videomodes);
#else
                savedata.hwscale += dir * 0.25;
                if(savedata.hwscale < 0.0)
                {
                    savedata.hwscale = 0.0;
                }
                if(savedata.hwscale > 4.00)
                {
                    savedata.hwscale = 4.00;
                }
#endif
                break;
            case 6:
#ifndef ANDROID
                if (opengl || (!savedata.fullscreen && savedata.hwscale == 1.0))
                {
                    break;
                }
#endif
                savedata.hwfilter += dir;
                if(savedata.hwfilter < 0)
                {
                    savedata.hwfilter = 1;
                }
                if(savedata.hwfilter > 1)
                {
                    savedata.hwfilter = 0;
                }
                video_set_mode(videomodes);
				break;
            case 7:
                if(!savedata.fullscreen && savedata.hwscale < 2.0)
                {
                    break;
                }
                videomodes.filter += dir;
                if(videomodes.filter > BLITTER_MAX - 1)
                {
                    videomodes.filter = 0;
                }
                if(videomodes.filter < 0)
                {
                    videomodes.filter = BLITTER_MAX - 1;
                }
                savedata.swfilter = videomodes.filter;
                memset(pDeltaBuffer, 0x00, 1244160);
				video_set_mode(videomodes);
                break;
            case 8:
                video_stretch((savedata.stretch ^= 1));
                break;
#endif
#endif
            default:
                quit = 1;
            }
        }
    }
    savesettings();
    bothnewkeys = 0;
    videooptionsMenu = 0;
}
